local config = {
  str_homestory_N23dianying_90030101_1_dialog_content = "ฮึก...ฮึก! เราควรจะปลอดภัยที่นี่ ฉันใช้เวลา!",
  str_homestory_N23dianying_90030101_2_dialog_content = "เราควรจะเป็น ตามเงื่อนงำจากปริศนาข้อที่แล้ว เราปลอดภัยตราบเท่าที่เรายังอยู่ในแสงสว่าง",
  str_homestory_N23dianying_90030101_3_dialog_content = "ฮา... ในที่สุดฉันก็สามารถหายใจได้",
  str_homestory_N23dianying_90030101_4_dialog_content = "ฮา... ในที่สุดฉันก็สามารถหายใจได้ เหนื่อยกับการเป็นนางเอก",
  str_homestory_N23dianying_90030101_5_dialog_content = "ขอแสดงความนับถือลูกเรือที่เล่นเป็นฆาตกร เขาทุ่มเทเกินไปและไล่ตามเรามาตลอด!",
  str_homestory_N23dianying_90030101_6_dialog_content = "เขาไม่ต้องการการพักผ่อนเหรอ?",
  str_homestory_N23dianying_90030101_7_dialog_content = "นี่คือเกมหนีห้องที่ได้รับความนิยมมากที่สุด",
  str_homestory_N23dianying_90030101_8_dialog_content = "พนักงานเพียงคนเดียวคือลูกเรือที่เล่นสัตว์ประหลาดเพื่อเพิ่มการแช่",
  str_homestory_N23dianying_90030101_9_dialog_content = "ฉันต้องทำงานหนักหน่อยเพื่อซื้อตั๋วให้เรา!",
  str_homestory_N23dianying_90030101_10_dialog_content = "ชื่นชมค่ะ แต่ก็น่ากลัวและน่าเชื่อจนเกือบเอาจริงเอาจัง...",
  str_homestory_N23dianying_90030101_11_dialog_content = "แน่นอน. แต่มันน่ากลัวเกินไป—ไม่ใช่ว่าฉันกลัว",
  str_homestory_N23dianying_90030101_12_dialog_content = "หยุดคิดมากได้แล้ว คุยกันพอแล้ว.",
  str_homestory_N23dianying_90030101_13_dialog_content = "ตามตรรกะแล้ว หากเราไม่สามารถค้นหาและไขเบาะแสใหม่ๆ ได้ เราจะถูกบังคับให้เข้าสู่ส่วนต่อไปของเรื่องราว",
  str_homestory_N23dianying_90030101_14_dialog_content = "หากสิ่งนั้นเกิดขึ้น เราคงไม่สามารถหาจุดจบที่แท้จริงได้",
  str_homestory_N23dianying_90030101_15_dialog_content = "คุณถูก. ลองมองไปรอบๆ",
  str_homestory_N23dianying_90030101_16_dialog_content = "ภาพหลอนนี้จะต้องตกแต่งอย่างหมดจด ... ใช่ไหม?",
  str_homestory_N23dianying_90030101_17_dialog_content = "พวกเขาทำได้ดีในการสร้างบรรยากาศ",
  str_homestory_N23dianying_90030101_18_dialog_content = "นั่นเป็นกล่องระเบิดใช่มั้ย? เพียงเพื่อให้คุณตกใจทันทีที่คุณเปิดมัน",
  str_homestory_N23dianying_90030101_19_dialog_content = "รู้สึกถูกและเลอะเทอะที่จะใช้ของเหล่านี้ในการตกแต่ง",
  str_homestory_N23dianying_90030101_20_dialog_content = "นั่นคือ... หลุมฝังศพ?",
  str_homestory_N23dianying_90030101_21_dialog_content = "ดูเถิด มีมือยื่นออกมาจากหลุมศพ! มีกลไกบางอย่างที่ควบคุมมันหรือไม่?",
  str_homestory_N23dianying_90030101_22_dialog_content = "แต่ทำไมถึงมีแจกัน...?",
  str_homestory_N23dianying_90030101_23_dialog_content = "ต้องการที่จะให้มันถู? บางทีบางสิ่งบางอย่างจะออกมา",
  str_homestory_N23dianying_90030101_24_dialog_content = "ล-อย่า!",
  str_homestory_N23dianying_90030101_24X1_dialog_content = "ช่างน่าตื่นเต้นจริงๆ ชับบ์",
  str_homestory_N23dianying_90030101_25_dialog_content = "นั่นหน้ากากผีกับหมวกนั่นเหรอ?",
  str_homestory_N23dianying_90030101_26_dialog_content = "ฉันสงสัยว่าจะเกิดอะไรขึ้นถ้าเราใส่มัน เราจะเปลี่ยนเป็นสิ่งมีชีวิตอื่นได้หรือไม่?",
  str_homestory_N23dianying_90030101_27_dialog_content = "ล-อย่ามายุ่ง!",
  str_homestory_N23dianying_90030101_27X1_dialog_content = "อยากสัมผัส ชับบ์!",
  str_homestory_N23dianying_90030101_28_dialog_content = "นั่นโทรศัพท์เหรอ?",
  str_homestory_N23dianying_90030101_29_dialog_content = "บางทีมันอาจจะดังขึ้นทันที และเสียงที่น่าสะพรึงกลัวอาจทำให้คุณกลัวจากอีกด้านหนึ่ง!",
  str_homestory_N23dianying_90030101_30_dialog_content = "ฮึ ขอเพียงแค่อยู่ห่างจากมัน",
  str_homestory_N23dianying_90030101_30X1_dialog_content = "มันทำให้ฉันอยากรู้จริงๆ ชับบ์",
  str_homestory_N23dianying_90030101_31_dialog_content = "ไม่ต้องกลัว",
  str_homestory_N23dianying_90030101_32_dialog_content = "กฎเกณฑ์มีความชัดเจน เราจะปลอดภัยตราบใดที่เราอยู่ในแสงสว่าง",
  str_homestory_N23dianying_90030101_33_dialog_content = "นักฆ่าคลั่งจะไม่—",
  str_homestory_N23dianying_90030101_34_dialog_content = "หวาา!",
  str_homestory_N23dianying_90030101_35_dialog_content = "เกิดอะไรขึ้น? ทำไมไฟกระพริบ?",
  str_homestory_N23dianying_90030101_35X1_dialog_content = "มันน่ากลัวมาก!",
  str_homestory_N23dianying_90030101_35X2_dialog_content = "สิ่งมหัศจรรย์กำลังจะเกิดขึ้น!",
  str_homestory_N23dianying_90030101_35X3_dialog_content = "กำลังจะเริ่มต้นเร็ว ๆ นี้? ชับบ์.",
  str_homestory_N23dianying_90030101_36_dialog_content = "ประตูติดอยู่!",
  str_homestory_N23dianying_90030101_37_dialog_content = "เดี๋ยวก่อน... มีคนอยู่ที่นั่น!",
  str_homestory_N23dianying_90030101_38_dialog_content = "เดี๋ยวก่อน... มีคนอยู่ที่นั่น! แฟนที่สะกดรอยตามคนอื่น?",
  str_homestory_N23dianying_90030101_39_dialog_content = "อา! คุณสามารถเห็นฉัน?",
  str_homestory_N23dianying_90030101_40_dialog_content = "โอ้? คุณสามารถพบฉัน ผู้เยี่ยมชม?",
  str_homestory_N23dianying_90030101_41_dialog_content = "ว-คุณเป็นใคร?",
  str_homestory_N23dianying_90030101_42_dialog_content = "ฉันคือภูตผีที่ติดอยู่ที่นี่",
  str_homestory_N23dianying_90030101_43_dialog_content = "ฉัน... ฉันคือภูตผีที่ถูกผูกไว้ที่นี่",
  str_homestory_N23dianying_90030101_44_dialog_content = "ผี?",
  str_homestory_N23dianying_90030101_45_dialog_content = "อ่า อย่ากลัวไปเลย",
  str_homestory_N23dianying_90030101_46_dialog_content = "ใช่ แต่อย่ากลัวเลย ฉันจะไม่ทำร้ายคุณ",
  str_homestory_N23dianying_90030101_47_dialog_content = "ฉันเป็นผีที่ดีและฉันมักจะไม่อยู่ในสายตา",
  str_homestory_N23dianying_90030101_48_dialog_content = "มันคงเป็นพรหมลิขิตที่เราพบกันในวันนี้",
  str_homestory_N23dianying_90030101_49_dialog_content = "มันคงเป็นพรหมลิขิตที่เราพบกันในวันนี้...",
  str_homestory_N23dianying_90030101_50_dialog_content = "อ้อ แล้วก็ไม่ต้องไปกังวลเรื่องแสงแวบๆ นั้นด้วย ไฟและประตูที่นี่ทำงานผิดปกติมาก เจ้าหน้าที่จะรีบดำเนินการแก้ไข",
  str_homestory_N23dianying_90030101_51_dialog_content = "แค่ใจเย็นและอดทน",
  str_homestory_N23dianying_90030101_52_dialog_content = "แค่ใจเย็นและอดทน บางทีฉันอาจแสดงกลเม็ดมายากลบางอย่างให้คุณดู เพื่อช่วยให้คุณฆ่าเวลาได้",
  str_homestory_N23dianying_90030101_53_dialog_content = "ไม่จำเป็นหรอก...",
  str_homestory_N23dianying_90030101_54_dialog_content = "โอ้ เรากำลังเล่นเกมหนีห้อง",
  str_homestory_N23dianying_90030101_55_dialog_content = "อ้อ... อีกอย่าง เรากำลังเล่นเกมหนีห้อง",
  str_homestory_N23dianying_90030101_56_dialog_content = "ถึงไฟจะดับ พนักงานก็ซ่อมทันที",
  str_homestory_N23dianying_90030101_57_dialog_content = "ไม่มีอันตรายที่คาดการณ์ได้",
  str_homestory_N23dianying_90030101_58_dialog_content = "ใช่ ทำไมไม่นั่งรอเจ้าหน้าที่จัดการล่ะ?",
  str_homestory_N23dianying_90030101_59_dialog_content = "ใช่. รับกาแฟดำสักแก้วมั้ยคะ? ฉันผิด ฉันลืมไปว่าตอนนี้ฉันเป็นผี และไม่สามารถชงกาแฟให้คุณได้อีก",
  str_homestory_N23dianying_90030101_60_dialog_content = "งั้นเราไปนั่งรอเจ้าหน้าที่กันเถอะ",
  str_homestory_N23dianying_90030101_61_dialog_content = "อืม... ฉันจะยืน ขอบคุณ.",
  str_homestory_N23dianying_90030101_62_dialog_content = "ก็ไม่มีอะไรให้ผู้หญิงนั่ง",
  str_homestory_N23dianying_90030101_63_dialog_content = "คุณอาจเป็นภาพหลอน แต่คุณค่อนข้างใส่ใจ",
  str_homestory_N23dianying_90030101_64_dialog_content = "แล้วเรื่องราวของคุณ...หรือความปรารถนาคืออะไร? บางทีเราสามารถช่วย?",
  str_homestory_N23dianying_90030101_65_dialog_content = "จริงหรือ นั่นเป็นความใจดีอย่างมากของคุณ.",
  str_homestory_N23dianying_90030101_66_dialog_content = "จริงหรือ แล้วขอบคุณสำหรับปัญหาของคุณ",
  str_homestory_N23dianying_90030101_67_dialog_content = "เป็นการดีที่จะเตือนพนักงานให้แก้ไขสิ่งต่าง ๆ ได้เร็วขึ้นในครั้งต่อไป",
  str_homestory_N23dianying_90030101_68_dialog_content = "ฉันติดอยู่ที่นี่นานกว่าหนึ่งสัปดาห์ก่อนที่พวกเขาจะเปิดประตูนั้นในที่สุด",
  str_homestory_N23dianying_90030101_69_dialog_content = "ฮะ? สัปดาห์?",
  str_homestory_N23dianying_90030101_70_dialog_content = "โอ้... ฉันต้องไป โปรดดูแลตัวเองด้วย",
  str_homestory_N23dianying_90030101_71_dialog_content = "สำหรับข้อมูลของคุณ ฉันตายที่นี่",
  str_homestory_N23dianying_90030101_72_dialog_content = "ว-เดี๋ยวก่อน!",
  str_homestory_N23dianying_90030101_73_dialog_content = "ผี...หายไป?",
  str_homestory_N23dianying_90030101_74_dialog_content = "นั่นเป็นภาพหลอนที่แท้จริง... และไม่ใช่นักแสดงใช่ไหม?",
  str_homestory_N23dianying_90030101_75_dialog_content = "นั่นเป็นภาพหลอนที่แท้จริง...ไม่ใช่นักแสดง",
  str_homestory_N23dianying_90030101_76_dialog_content = "ฉันหมายถึง เราจะไม่ถูกขังที่นี่เป็นเวลาหนึ่งสัปดาห์ใช่ไหม",
  str_homestory_N23dianying_90030101_77_dialog_content = "เธอสามารถพูดความจริงได้หรือไม่? เราจะถูกขังอยู่ที่นี่เป็นเวลาหนึ่งสัปดาห์หรือไม่?",
  str_homestory_N23dianying_90030101_78_dialog_content = "ต-เป็นไปไม่ได้! ตอนนั้นต้องมีบางอย่างผิดพลาด...",
  str_homestory_N23dianying_90030101_79_dialog_content = "แน่นอนพวกเขาจะมาหาเราเร็วขึ้นในครั้งนี้",
  str_homestory_N23dianying_90030101_80_dialog_content = "เฮ้ ไฟเริ่มกะพริบอีกครั้ง... ห๊ะ? ตอนนี้กลับมาเป็นปกติแล้ว",
  str_homestory_N23dianying_90030101_81_dialog_content = "ดู? บอกคุณแล้ว!",
  str_homestory_N23dianying_90030101_82_dialog_content = "หืม? ภูตผีนั่นไม่ใช่เหรอ?",
  str_homestory_N23dianying_90030101_83_dialog_content = "เฮียกลับมาทำไม",
  str_homestory_N23dianying_90030101_84_dialog_content = "เฮ้...?",
  str_homestory_N23dianying_90030101_85_dialog_content = "รอ! ไม่ใช่ผีตัวเดียวกัน!",
  str_homestory_N23dianying_90030101_85X1_dialog_content = "อะไรนะ!",
  str_homestory_N23dianying_90030101_85X2_dialog_content = "ฉันขนลุก ชับบ์!",
  str_homestory_N23dianying_90030101_86_dialog_content = "หา...ไปหาความจริง...",
  str_homestory_N23dianying_90030101_87_dialog_content = "ดูเหมือนอยากให้เรา... ดูหนังสือเล่มนั้น",
  str_homestory_N23dianying_90030101_88_dialog_content = "มันต้องการให้เราตรวจสอบหนังสือเล่มนั้น ฉันคุ้นเคยกับสายตาที่เร่าร้อนและกระตือรือร้นแบบนั้น",
  str_homestory_N23dianying_90030101_89_dialog_content = "ต้องเป็นอย่างนั้น... แต่... ขอโทษนะ อะไรอยู่ในหนังสือ?",
  str_homestory_N23dianying_90030101_90_dialog_content = "หา...ไปหาความจริง...",
  str_homestory_N23dianying_90030101_91_dialog_content = "คุณพูดอย่างอื่นได้ไหม",
  str_homestory_N23dianying_90030101_92_dialog_content = "ฉันไม่ได้เพิ่งบอกคุณเหรอ? ค้นหามัน... ไปค้นหาความจริง!",
  str_homestory_N23dianying_90030101_93_dialog_content = "ว้าว! มันโกรธ!",
  str_homestory_N23dianying_90030101_94_dialog_content = "ฉันเดาว่าเราจะต้องตรวจสอบมัน",
  str_homestory_N23dianying_90030101_95_dialog_content = "นี่มัน...!",
  str_homestory_N23dianying_90030101_96_option_content = "วารสาร",
  str_homestory_N23dianying_90030101_97_dialog_content = "นางเอก คุณเปิดมันและตระหนักว่ามันเป็นบันทึก",
  str_homestory_N23dianying_90030101_98_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_99_dialog_content = "เลดี้วิคตอเรีย โปรดลงโทษฉันด้วย ฉันสมควรได้รับมัน",
  str_homestory_N23dianying_90030101_100_dialog_content = "เลดี้วิกตอเรีย กรุณาอภัยให้บาปของฉันที่เกิดเป็นสัตว์ประหลาดน่ารังเกียจด้วย...",
  str_homestory_N23dianying_90030101_101_dialog_content = "ฉันพยายามทิ้ง Hunting Stone ไว้ที่ Soroz และปล่อยให้อยู่คนเดียว",
  str_homestory_N23dianying_90030101_102_dialog_content = "แต่ก็กลับมาไม่ทัน!",
  str_homestory_N23dianying_90030101_103_dialog_content = "มีวิธีกำจัดมันหรือไม่? ใครที่กำลังดูเรื่องนี้อยู่ ฉันจะจ่ายให้คุณในราคาที่มหาศาลเพื่อกำจัดมันให้ฉัน",
  str_homestory_N23dianying_90030101_104_dialog_content = "เฮ้ ไม่มีความโปรดปรานส่วนตัว ชับบ์!",
  str_homestory_N23dianying_90030101_105_dialog_content = "เราคงลำบากมากถ้าใครเห็นสิ่งนี้ ชับบ์!",
  str_homestory_N23dianying_90030101_106_dialog_content = "ม-นี่คือพร็อพที่ถูกต้องหรือไม่?",
  str_homestory_N23dianying_90030101_107_dialog_content = "ดูเหมือนว่าจะเป็นบันทึกของเขาเอง!",
  str_homestory_N23dianying_90030101_108_dialog_content = "มันยากมากที่จะจินตนาการ...",
  str_homestory_N23dianying_90030101_109_dialog_content = "ลงชื่อ... รู้สึกเหมือนเป็นผีที่ขมขื่นมากกว่าผี",
  str_homestory_N23dianying_90030101_110_dialog_content = "คนใน True Order เป็นคนแปลก ๆ ทั้งหมดที่ไม่ใช่ฉันหรือไม่?",
  str_homestory_N23dianying_90030101_111_dialog_content = "ฉันเสียใจที่ได้อ่านบันทึกของคุณ",
  str_homestory_N23dianying_90030101_112_dialog_content = "ไม่... มันเป็นความผิดของฉันจริงๆ",
  str_homestory_N23dianying_90030101_113_dialog_content = "มันเป็นความเสียใจและความรอดของฉัน",
  str_homestory_N23dianying_90030101_114_dialog_content = "มาเร็ว! ไม่ต้องอ่านทั้งๆที่บอก!",
  str_homestory_N23dianying_90030101_115_dialog_content = "ใครเป็นคนเขียนบทงี่เง่านี้!?",
  str_homestory_N23dianying_90030101_116_dialog_content = "ฉันไม่รู้ว่าคุณหมายถึงอะไร แต่... เราควรถ่ายทำใหม่หลังจากตรวจสอบอุปกรณ์ประกอบฉากอีกครั้ง",
  str_homestory_N23dianying_90030101_117_option_content = "บันทึกการทำงาน",
  str_homestory_N23dianying_90030101_118_dialog_content = "นางเอก คุณเปิดมันและเริ่มอ่านออกเสียง",
  str_homestory_N23dianying_90030101_119_dialog_content = "XX.XX.XXXX",
  str_homestory_N23dianying_90030101_120_dialog_content = "อุปกรณ์ในโรงงานทำงานผิดปกติ ล็อกแขกในห้อง",
  str_homestory_N23dianying_90030101_121_dialog_content = "เจ้าหน้าที่ใช้เวลาสองสามวันในการซ่อมแซมฉุกเฉิน แต่...",
  str_homestory_N23dianying_90030101_122_dialog_content = "ทำไมคุณถึงอ่านบันทึกการทำงานของคนอื่น",
  str_homestory_N23dianying_90030101_123_dialog_content = "อ๊ะๆๆๆ—!",
  str_homestory_N23dianying_90030101_124_dialog_content = "จู่ๆจะตะโกนทำไม!? และคุณสามารถพูดอย่างอื่นได้!",
  str_homestory_N23dianying_90030101_125_dialog_content = "และคุณขอให้เราอ่านมัน!",
  str_homestory_N23dianying_90030101_126_dialog_content = "ยังคงเป็นไดอารี่ของฉัน! คุณไม่สามารถเพียงแค่อ่านมัน!",
  str_homestory_N23dianying_90030101_127_dialog_content = "ทำไมคุณถึงทิ้งบันทึกการทำงานไว้อย่างดีที่นั่น? อยากรู้จัง ชับบ์",
  str_homestory_N23dianying_90030101_128_dialog_content = "ต้องเป็นลูกเรืออุปกรณ์ประกอบฉากใช่ไหม? ชับบ์.",
  str_homestory_N23dianying_90030101_129_dialog_content = "หยุดทำตัวไร้เหตุผลได้แล้ว คุณเป็นใครกันแน่?",
  str_homestory_N23dianying_90030101_130_dialog_content = "ฉันเป็นพระเอก ฉันมีสิทธิ์ที่จะไม่มีเหตุผล! คุณตอบฉันดีกว่า ตัวละครข้าง!",
  str_homestory_N23dianying_90030101_131_dialog_content = "ฉันเป็นผี",
  str_homestory_N23dianying_90030101_132_dialog_content = "เรารู้แล้ว!",
  str_homestory_N23dianying_90030101_133_dialog_content = "ทำไมคุณถึงรู้ว่า? คุณเคยเห็นมาก่อนหรือไม่?",
  str_homestory_N23dianying_90030101_134_dialog_content = "ฉันเป็นผี ใครก็ได้บอกที",
  str_homestory_N23dianying_90030101_135_dialog_content = "ถูกต้อง!",
  str_homestory_N23dianying_90030101_136_dialog_content = "ถูกต้อง. คุณจึงไม่โง่อย่างที่เห็น",
  str_homestory_N23dianying_90030101_137_dialog_content = "เราทำ. แค่ตอนนี้ ที่นี่ จริงๆ แล้ว เธอบอกว่าเธอเสียชีวิตที่นี่เพราะเจ้าหน้าที่ซ่อมอุปกรณ์ไม่ทันเพื่อช่วยเธอ",
  str_homestory_N23dianying_90030101_138_dialog_content = "เราแน่ใจว่าทำ แค่ตอนนี้ ที่นี่ จริงๆ แล้ว",
  str_homestory_N23dianying_90030101_139_dialog_content = "เธอบอกว่าเธอเสียชีวิตเพราะช่างซ่อมที่โง่เขลา",
  str_homestory_N23dianying_90030101_140_dialog_content = "โอ้ช่างน่าเสียดาย",
  str_homestory_N23dianying_90030101_141_dialog_content = "อะไร เธอบอกว่าลับหลังฉัน?",
  str_homestory_N23dianying_90030101_142_dialog_content = "ฉันเป็นช่างซ่อมคนนั้น",
  str_homestory_N23dianying_90030101_143_dialog_content = "ฉันพยายามจะแงะประตูให้เปิด แต่มีบางอย่างผิดพลาด ดังนั้นฉันจึงติดอยู่ระหว่างนั้นและเสียชีวิต",
  str_homestory_N23dianying_90030101_144_dialog_content = "ฉันพยายามจะแงะประตูให้เปิด แต่มีบางอย่างผิดพลาด ดังนั้นฉันจึงติดอยู่ระหว่างนั้นและเสียชีวิต โง่ใช่มั้ย?",
  str_homestory_N23dianying_90030101_145_dialog_content = "อืม... ขอแสดงความเสียใจ",
  str_homestory_N23dianying_90030101_146_dialog_content = "ดีดูที่ด้านสว่าง ถ้าช่างซ่อมโง่ตายไปแล้ว คงไม่ใช่เขาที่มาช่วยเรา",
  str_homestory_N23dianying_90030101_147_dialog_content = "ดังนั้นคนอื่นควรจะมาที่นี่เร็ว ๆ นี้",
  str_homestory_N23dianying_90030101_148_dialog_content = "เซฟคุณ? แล้วทำไมคุณถึงมาอยู่ที่นี่ล่ะ?",
  str_homestory_N23dianying_90030101_149_dialog_content = "สำรวจสิ่งที่เหลืออยู่ของห้องหลบหนีนั้นหรือไม่? สบายแค่ไหน.",
  str_homestory_N23dianying_90030101_150_dialog_content = "สำรวจสิ่งที่เหลืออยู่ของห้องหลบหนีนั้นหรือไม่? คุณค่อนข้างกล้าหาญใช่มั้ย",
  str_homestory_N23dianying_90030101_151_dialog_content = "คุณหมายถึงอะไร ซากห้องหลบหนี?",
  str_homestory_N23dianying_90030101_152_dialog_content = "นั่นคือสิ่งที่ดูเหมือน สถานที่นี้ถูกปิดมาระยะหนึ่งแล้ว",
  str_homestory_N23dianying_90030101_153_dialog_content = "คิดเกี่ยวกับมัน หลังจากเกิดอุบัติเหตุที่คร่าชีวิตผู้คนไป 2 คน ไม่มีทางที่สถานที่แห่งนี้จะยังคงเปิดดำเนินการอยู่",
  str_homestory_N23dianying_90030101_154_dialog_content = "คุณกลับบ้านดีกว่า ฉันจะไปนอนแล้ว.",
  str_homestory_N23dianying_90030101_155_dialog_content = "คุณกลับบ้านดีกว่า ฉันจะหาวิธีกำจัดหินล่าสัตว์",
  str_homestory_N23dianying_90030101_156_dialog_content = "เดี๋ยวก่อน... คุณกำลังพูดอะไร? ผีต้องนอนไหม?",
  str_homestory_N23dianying_90030101_157_dialog_content = "มันหายไปแล้ว...",
  str_homestory_N23dianying_90030101_158_dialog_content = "เขาหมายความว่าอย่างไร ... มันถูกปิดตัวลง?",
  str_homestory_N23dianying_90030101_159_dialog_content = "ปิดตัวลง? แต่เราเข้ามาที่นี่ด้วยตั๋วของเรา!",
  str_homestory_N23dianying_90030101_160_dialog_content = "ที่จริงแล้ว ถ้าคุณคิดอย่างนั้นจริงๆ... ไม่มีใครอยู่ที่นั่นเพื่อตรวจตั๋วของเรา และเราไม่เห็นใครเลยยกเว้นนักฆ่าคลั่งคนนั้น",
  str_homestory_N23dianying_90030101_161_dialog_content = "ฉันคิดว่าคุณพูดเพราะมันเพิ่มการแช่!",
  str_homestory_N23dianying_90030101_162_dialog_content = "ฉันก็คิดเหมือนกัน",
  str_homestory_N23dianying_90030101_163_dialog_content = "แต่ไม่มีใครมาช่วยเรา? นี่เราติดอยู่จริงๆเหรอ...?",
  str_homestory_N23dianying_90030101_164_dialog_content = "แต่นักฆ่าเลื่อยไฟฟ้าคนนั้น... เขาคงเป็นพนักงานใช่ไหม?",
  str_homestory_N23dianying_90030101_165_dialog_content = "ฉันไม่รู้... ฉันไม่รู้ว่าเขาควรจะเป็นใครหรืออย่างไร!",
  str_homestory_N23dianying_90030101_166_dialog_content = "เฮ้! ไฟดับอีกแล้วววว! ประตูยังติดอยู่หรือไม่?",
  str_homestory_N23dianying_90030101_167_dialog_content = "มันเริ่มเก่าแล้ว... ฉันไม่กลัวเลย!",
  str_homestory_N23dianying_90030101_168_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก!</color>",
  str_homestory_N23dianying_90030101_169_dialog_content = "ฟัง! เสียงฝีเท้าจากอีกด้านของประตู...",
  str_homestory_N23dianying_90030101_170_dialog_content = "รอยเท้า? จากอีกด้านของประตู...",
  str_homestory_N23dianying_90030101_171_dialog_content = "ใคร...",
  str_homestory_N23dianying_90030101_172_option_content = "ม้วนลึกลับ",
  str_homestory_N23dianying_90030101_173_dialog_content = "นางเอกเปิดม้วนหนังสือลึกลับรูปทรงประหลาดนี้และเริ่มอ่าน",
  str_homestory_N23dianying_90030101_174_dialog_content = "ได้ยินฉัน!",
  str_homestory_N23dianying_90030101_175_dialog_content = "พระเจ้าแห่งความว่างเปล่าไม่มีที่สิ้นสุด",
  str_homestory_N23dianying_90030101_176_dialog_content = "ผู้พิชิตความหวาดกลัวและความกลัว",
  str_homestory_N23dianying_90030101_177_dialog_content = "บุตรแห่งความว่างเปล่าและความโกลาหล",
  str_homestory_N23dianying_90030101_178_dialog_content = "จอห์นนี่ จอมมารผู้ยิ่งใหญ่แห่งการทำอาหาร!",
  str_homestory_N23dianying_90030101_179_dialog_content = "ฉันเสียสละหนอนทรายที่อร่อยและสดที่สุดให้คุณ!",
  str_homestory_N23dianying_90030101_180_dialog_content = "คนรับใช้ของคุณกำลังรอคุณอยู่!",
  str_homestory_N23dianying_90030101_181_dialog_content = "...",
  str_homestory_N23dianying_90030101_182_dialog_content = "...",
  str_homestory_N23dianying_90030101_183_dialog_content = "นั่นไม่ใช่เรื่องของฉัน...",
  str_homestory_N23dianying_90030101_184_dialog_content = "ผู้อำนวยการ! เห็นได้ชัดว่ามีบางอย่างผิดปกติกับอุปกรณ์ประกอบฉาก!",
  str_homestory_N23dianying_90030101_185_dialog_content = "เรามีช่องว่างมากมายสำหรับการปรับปรุงในแง่ของอุปกรณ์ประกอบฉาก คุณว่าไหม? ชับบ์.",
  str_homestory_N23dianying_90030101_186_dialog_content = "ฮะ? หาอะไร? คุณกำลังพูดถึงอะไร",
  str_homestory_N23dianying_90030101_187_dialog_content = "หา...ไปหาความจริง...",
  str_homestory_N23dianying_90030101_188_dialog_content = "ฉันไม่ได้เพิ่งบอกคุณเหรอ? ค้นหามัน... ไปค้นหาความจริง!",
  str_homestory_N23dianying_90030101_189_dialog_content = "แต่ไม่มีอะไรในทิศทางนั้น!",
  str_homestory_N23dianying_90030101_190_dialog_content = "ไม่? เป็นไปได้ยังไง?",
  str_homestory_N23dianying_90030101_191_dialog_content = "ไม่เห็นเหรอ? เป็นที่ที่เนื้อถูกฉีกออกเป็นชิ้นๆ และวิญญาณก็กลืนกิน",
  str_homestory_N23dianying_90030101_192_dialog_content = "ที่ซึ่งข้าพเจ้าได้วางสำเนาหลักคำสอนที่เขียนด้วยลายมือ",
  str_homestory_N23dianying_90030101_193_dialog_content = "ฉันคิดว่ามีบางอย่างผิดปกติกับอุปกรณ์ประกอบฉาก...",
  str_homestory_N23dianying_90030101_194_dialog_content = "และ Nails คุณไม่ได้ทำตามสายของคุณ!",
  str_homestory_N23dianying_90030101_195_dialog_content = "ฉันขอโทษ...ฉันจะขอโทษและสารภาพด้วยเล็บ...",
  str_homestory_N23dianying_90030101_196_dialog_content = "หยุด หยุด หยุด! นี่ไม่ใช่หนังสยองขวัญเลือด! มันจะเลอะชุดด้วย!",
  str_homestory_N23dianying_90030101_197_dialog_content = "มันยากมากที่จะจินตนาการ...",
  str_homestory_N23dianying_90030101_198_dialog_content = "ปิดฝาไว้เลยไหม หยุดนำความอับอายมาสู่ชื่อ True Order!",
  str_homestory_N23dianying_90030101_199_dialog_content = "มองไม่เห็นจริงๆเหรอ? ทีมงานพร็อพดร็อปบอลจริงๆ!",
  str_homestory_N23dianying_90030101_200_dialog_content = "การแสดงด้วยอุปกรณ์ประกอบฉากในจินตนาการนั้นไม่น่าเชื่อถือเลย!",
  str_homestory_N23dianying_90030101_201_dialog_content = "อุปกรณ์ประกอบฉากและชุดทั้งหมดรู้สึกถูก นี่ไม่ใช่วิธีสร้างหนังคุณภาพ!",
  str_homestory_N23dianying_90030101_202_dialog_content = "ดีคุณมีประเด็น",
  str_homestory_N23dianying_90030101_203_dialog_content = "มีบางอย่างผิดปกติ โดยเฉพาะอย่างยิ่งเมื่อ Brock คิดอย่างนั้น",
  str_homestory_N23dianying_90030101_204_dialog_content = "เฮ้! มันหมายความว่ายังไง!?",
  str_homestory_N23dianying_90030101_205_dialog_content = "อย่างไรก็ตาม เราควรเตรียมอุปกรณ์ประกอบฉากให้พร้อมแล้วถ่ายใหม่",
  str_homestory_N23dianying_90030101_206_dialog_content = "ไม่เป็นไร. ในฐานะนางเอก ฉันอดทน เราจะกลับมาอีกเมื่อชุดพร้อม",
  str_homestory_N23dianying_90030201_1_dialog_content = "นี่คือส่วนที่ลึกที่สุดของถ้ำมังกรในตำนาน—โถงสมบัติ...?",
  str_homestory_N23dianying_90030201_2_dialog_content = "นี่ต้องเป็น Frost Mirror ในตำนานแน่ๆ! มันสามารถตอบคำถามใด ๆ ที่คุณถามและมีพลังเวทย์มนตร์ที่ไม่สิ้นสุด!",
  str_homestory_N23dianying_90030201_2X1_dialog_content = "Frost Mirror ในตำนานต้องอยู่ที่นี่แล้ว! มันสามารถตอบคำถามใด ๆ ที่คุณถามและมีพลังเวทย์มนตร์ที่ไม่สิ้นสุด!",
  str_homestory_N23dianying_90030201_3_dialog_content = "ฉันไม่รู้ว่ามังกรเฝ้ากระจกโง่ๆ ตัวนั้นไปไหน แต่การได้มันมานี่ช่างยากเหลือเกิน",
  str_homestory_N23dianying_90030201_3X1_dialog_content = "ฉันไม่รู้ว่ามังกรเฝ้ากระจกโง่ๆ ตัวนั้นไปไหน แต่การย่องเข้ามาที่นี่เป็นเรื่องกล้วยๆ",
  str_homestory_N23dianying_90030201_4_dialog_content = "ตราบใดที่เราเอามันออกไปจากที่นี่จริงๆ... จะมีคนมากมายขอจ่ายเงินทางจมูกเพื่อมัน ใครจะไปรู้ กษัตริย์อาจให้ตำแหน่งและที่ดินแก่ฉันด้วยซ้ำ!",
  str_homestory_N23dianying_90030201_4X1_dialog_content = "หรือฉันสามารถใช้พลังของมันเพื่อทำเงินได้มากมาย! ฉันจะเข้าร่วมรายการรวยในเวลาไม่นาน!",
  str_homestory_N23dianying_90030201_5_dialog_content = "ฮ่าฮ่าฮ่า... ในที่สุดสมบัติหายากเช่นนี้ก็อยู่ในมือของบาร์บาโตส พ่อค้าอาชญากรที่ยิ่งใหญ่ที่สุดตลอดกาล!",
  str_homestory_N23dianying_90030201_6_dialog_content = "ซ-งั้น... อะแฮ่ม งั้นฉันจะช่วยเอง",
  str_homestory_N23dianying_90030201_6X1_dialog_content = "พวกเขาจะเข้าใจผิดได้อย่างไร? ชับบ์.",
  str_homestory_N23dianying_90030201_6X2_dialog_content = "คุณทำได้ เรวี่!",
  str_homestory_N23dianying_90030201_6X3_dialog_content = "ค่าจ้างของพวกเขาควรจะเทียบท่าเพราะพูดผิดใช่ไหม? ชับบ์.",
  str_homestory_N23dianying_90030201_7_dialog_content = "โอ้? มีคนเข้ามาใกล้ แต่ทำไมพวกเขาถึงมาอยู่ในหอสมบัติ...?",
  str_homestory_N23dianying_90030201_7X1_dialog_content = "อะไร ฉันสาบานว่าฉันได้ดูทุกที่ แต่ไม่มีอะไรที่ดูเหมือนกระจกวิเศษ",
  str_homestory_N23dianying_90030201_8_dialog_content = "อ้อ ลืมไป ไม่มีเวลาแล้ว ฉันจะหลบหลังกระจกก่อน",
  str_homestory_N23dianying_90030201_8X1_dialog_content = "แน่นอนว่าไม่มีใครสามารถขโมยกระจกไปแล้วได้...?",
  str_homestory_N23dianying_90030201_9_dialog_content = "พบแล้ว! เจอแล้ว-!!",
  str_homestory_N23dianying_90030201_9X1_dialog_content = "พบแล้ว! เจอแล้ว-!! นี่จะต้องเป็นขั้นตอนสุดท้าย!",
  str_homestory_N23dianying_90030201_10_dialog_content = "ให้ฉันดูหน่อย. อืม... ต้นไม้ริบหรี่ที่สวยงามนี้...",
  str_homestory_N23dianying_90030201_10X1_dialog_content = "ให้ฉันได้ดูต้นไม้ริบหรี่ที่สวยงามนี้!",
  str_homestory_N23dianying_90030201_11_dialog_content = "อืม... รูปปั้น Frost Dragon ไร้สาระ",
  str_homestory_N23dianying_90030201_11X1_dialog_content = "นอกจากนี้ยังมีรูปปั้น Frost Dragon ที่น่าประทับใจอีกด้วย!",
  str_homestory_N23dianying_90030201_14_dialog_content = "ยอดเยี่ยม! ต้องใช้ความพยายามอย่างมาก แต่ในที่สุดเราก็สามารถเอาชนะ Frost Dragon ได้ และทำให้มันสำเร็จที่นี่!",
  str_homestory_N23dianying_90030201_14X1_dialog_content = "ยอดเยี่ยม! ต้องใช้ความพยายามอย่างมาก แต่ในที่สุดเราก็สามารถเอาชนะ Frost Dragon ได้ และทำให้มันสำเร็จที่นี่! แล้วรางวัลสูงสุดอยู่ที่ไหน?",
  str_homestory_N23dianying_90030201_16_dialog_content = "ฮะ...? นี่มันตุ๊กตาหมีเหรอ? Frost Dragons ชอบอะไรแบบนี้ด้วยเหรอ?",
  str_homestory_N23dianying_90030201_16X1_dialog_content = "อะไรเนี่ย? ตุ๊กตาหมี? อ่าฮะ! Frost Dragons ชอบสิ่งนี้ด้วยหรือไม่?",
  str_homestory_N23dianying_90030201_17_dialog_content = "มองไม่เห็นเลยจริงๆ...",
  str_homestory_N23dianying_90030201_17X1_dialog_content = "แค่ดูไม่ได้!",
  str_homestory_N23dianying_90030201_18_dialog_content = "ดูเหมือนว่าจะเข้ากับข่าวลือโดยพื้นฐาน",
  str_homestory_N23dianying_90030201_18X1_dialog_content = "โดยพื้นฐานแล้วสอดคล้องกับข่าวลือ",
  str_homestory_N23dianying_90030201_19_dialog_content = "สถานที่แห่งนี้ควรเป็น Hall of Treasures ซึ่งได้รับการปกป้องโดย Frost Dragon",
  str_homestory_N23dianying_90030201_19X1_dialog_content = "สถานที่แห่งนี้ควรเป็น Hall of Treasures ซึ่งได้รับการปกป้องโดย Frost Dragon!",
  str_homestory_N23dianying_90030201_22_dialog_content = "โอ้? นี่อะไร...? มันดูไม่เข้าท่า",
  str_homestory_N23dianying_90030201_22X1_dialog_content = "โอ้? อะไรเนี่ย? มันดูนอกสถานที่โดยสิ้นเชิง",
  str_homestory_N23dianying_90030201_23_dialog_content = "ว่ากันว่ามังกรก็เก็บของแปลก ๆ เหมือนกัน เลยคิดว่าน่าจะเข้าใจได้",
  str_homestory_N23dianying_90030201_23X1_dialog_content = "ดูเหมือนว่า Frost Dragons จะไม่สว่างขนาดนั้น บางทีก็วางผิดที่",
  str_homestory_N23dianying_90030201_27_dialog_content = "ขอฉันดูหน่อย... อืม นี่ไม่ใช่ราวแขวนเสื้อผ้าเหรอ?",
  str_homestory_N23dianying_90030201_27X1_dialog_content = "ให้ฉันดู. ฮะ? นี่คือราวแขวนเสื้อผ้า?",
  str_homestory_N23dianying_90030201_28_dialog_content = "และถ้าคุณดูเสื้อผ้าที่อยู่บนนั้น พวกมันดูเหมือนของที่ตัวละครในเทพนิยายจะใส่ไม่ใช่เหรอ?",
  str_homestory_N23dianying_90030201_28X1_dialog_content = "แล้วทำไมถึงมีเสื้อผ้าผู้หญิงอยู่บนนั้น? เป็นไปได้ไหมที่ Frost Dragon สามารถแปลงร่างเป็นเด็กผู้หญิงได้?",
  str_homestory_N23dianying_90030201_37_dialog_content = "นี่คือหอสมบัติจริงหรือ?",
  str_homestory_N23dianying_90030201_37X1_dialog_content = "นี่คือหอสมบัติจริงหรือ? เราไม่ได้ทำผิดพลาด?",
  str_homestory_N23dianying_90030201_38_dialog_content = "แน่นอนมันเป็น! เราไม่ได้ผ่านปัญหาทั้งหมดนั้นและเอาชนะ Frost Dragon เพื่อสร้างมันขึ้นมาที่นี่ใช่หรือไม่!",
  str_homestory_N23dianying_90030201_38X1_dialog_content = "แน่นอนมันเป็น! เราไม่ได้ผ่านปัญหาทั้งหมดนั้นและเอาชนะ Frost Dragon เพื่อสร้างมันขึ้นมาที่นี่ใช่หรือไม่! แถมบทแนะนำก็อยู่ที่นี่ด้วย!",
  str_homestory_N23dianying_90030201_45_dialog_content = "ให้ฉันดู. อืม มีตุ๊กตาหิมะที่น่ารักด้วย!",
  str_homestory_N23dianying_90030201_45X1_dialog_content = "ให้ฉันดู. ฮะ? ทำไมมนุษย์หิมะถึงมี? ทำให้ฉันนึกถึงการทำกับเพื่อนของฉัน",
  str_homestory_N23dianying_90030201_46_dialog_content = "ไม่เห็นจะละลายเลย Frost Dragon สร้างมันขึ้นมาด้วยพลังของมันเองเหรอ?",
  str_homestory_N23dianying_90030201_46X1_dialog_content = "ไม่เห็นจะละลายเลย ค่อนข้างน่าประทับใจ",
  str_homestory_N23dianying_90030201_63_dialog_content = "(อะ-อะไรนะ...! พวกเหล่านี้สามารถเอาชนะ Frost Dragon ได้จริงหรือ คนที่บอกว่าสามารถเอาชนะกองทัพทั้งหมดได้ในพริบตา?)",
  str_homestory_N23dianying_90030201_63X1_dialog_content = "ฮะ?! ที่น่าตื่นตาตื่นใจ?",
  str_homestory_N23dianying_90030201_63X2_dialog_content = "นี่คือสิ่งที่ทรงพลัง ชับบ์",
  str_homestory_N23dianying_90030201_63X3_dialog_content = "ฉันไม่เชื่อหรอก ชับบ์",
  str_homestory_N23dianying_90030201_64_dialog_content = "(ฉันควรแสดงตัวไหม...? บางทีถ้าฉันอธิบายว่าฉันเป็นแค่ขโมยหรือพ่อค้าหรืออะไรทำนองนั้น มันจะป้องกันไม่ให้พวกเขาคิดว่าฉันเป็นศัตรูหากถูกค้นพบ...)",
  str_homestory_N23dianying_90030201_65_dialog_content = "มันคงแย่มากถ้าพวกเขาเข้าใจผิดว่าฉันเป็นสัตว์ประหลาดและไล่ตามฉัน...",
  str_homestory_N23dianying_90030201_66_dialog_content = "ไม่ต้องยากขนาดนี้",
  str_homestory_N23dianying_90030201_67_dialog_content = "นี่เป็นเพราะคุณสุ่มสี่สุ่มห้าไว้วางใจคนที่คุณพบในเขาวงกต",
  str_homestory_N23dianying_90030201_68_dialog_content = "พ่อค้าคนนั้นบอกว่าเขาพบอุปกรณ์หายากมากมายในดันเจี้ยน และคุณก็แค่รีบไปแลกเปลี่ยนกับเขา แต่ทั้งหมดเป็นของปลอม!",
  str_homestory_N23dianying_90030201_69_dialog_content = "เหตุการณ์นั้นทำให้เราอยู่ในสถานะทางการเงินที่ยากลำบากมาก",
  str_homestory_N23dianying_90030201_69X1_dialog_content = "เหตุการณ์นั้นทำให้เราอยู่ในสถานะทางการเงินที่ยากลำบากมาก!",
  str_homestory_N23dianying_90030201_70_dialog_content = "และตอนนี้ทุกคนก็หยุดงาน แม้แต่ Miss Healer ก็ออกไปช่วยเหลือผู้บาดเจ็บเพื่อนำเงินมาบางส่วน",
  str_homestory_N23dianying_90030201_71_dialog_content = "ฮะ? โอ้ ไม่ต้องห่วงฉัน! ฉันมีความสุขในการรักษาอาการบาดเจ็บของผู้อื่น",
  str_homestory_N23dianying_90030201_72_dialog_content = "อืม เอ่อ... นั่นเป็นเพียงการตัดสินชั่วขณะ ฉันระมัดระวังมากขึ้นตั้งแต่นั้นมา!",
  str_homestory_N23dianying_90030201_72X1_dialog_content = "อืม เอ่อ... นั่นเป็นเพียงการตัดสินชั่วขณะ",
  str_homestory_N23dianying_90030201_72X2_dialog_content = "ฉันไม่ได้คาดหวังว่า NPC ที่ดูไม่เป็นอันตรายจะเป็นภัยคุกคาม",
  str_homestory_N23dianying_90030201_73_dialog_content = "มันไม่ระวังเท่าไหร่นักหรอก... และหลังจากนั้นก็มีหัวขโมยที่อ้างว่าสามารถช่วยเราปลดอาวุธกับดักในดันเจี้ยนได้",
  str_homestory_N23dianying_90030201_73X1_dialog_content = "โอ้จริงเหรอ? หลังจากนั้นก็มาถึงโจร ซึ่งอ้างว่าสามารถช่วยเราปลดอาวุธกับดักในดันเจี้ยนได้",
  str_homestory_N23dianying_90030201_74_dialog_content = "แต่คุณปล่อยให้เขาเข้าร่วมกับเราเพราะคุณเกลียดการจัดการกับดักเท่านั้นที่จะตื่นขึ้นพร้อมกับอุปกรณ์ที่หายไปทั้งหมด?!",
  str_homestory_N23dianying_90030201_74X1_dialog_content = "คุณปล่อยให้เขาเข้าร่วมกับเราเพราะคุณเกลียดการจัดการกับดัก เพียงเพื่อจะตื่นขึ้นมาพร้อมกับอุปกรณ์ที่หายไปทั้งหมด!",
  str_homestory_N23dianying_90030201_75_dialog_content = "โชคดีที่มันเป็นอุปกรณ์ปกติทั้งหมด อุปกรณ์ขั้นสูงอยู่ที่ช่างตีเหล็กเพื่อทำการซ่อมแซม",
  str_homestory_N23dianying_90030201_76_dialog_content = "ไม่อย่างนั้นจะปวดหัวจริงๆ ที่ต้องเริ่มต้นใหม่จากความว่างเปล่า",
  str_homestory_N23dianying_90030201_77_dialog_content = "ฉันรู้แล้ว! ฉันจะไม่ไร้เดียงสาอีกต่อไปแล้ว!",
  str_homestory_N23dianying_90030201_77X1_dialog_content = "ฉันรู้แล้ว! กัดครั้งเดียวอายสองครั้ง!",
  str_homestory_N23dianying_90030201_78_dialog_content = "ถ้าฉันเจอใครที่อ้างว่าเป็นโจร หรือเป็นนักธุรกิจ หรือโดยพื้นฐานแล้วใครก็ตามที่น่าสงสัย ฉันจะนัดหยุดงานที่นั่นทันที ช่วยฉันให้ยุ่งยากหน่อย",
  str_homestory_N23dianying_90030201_79_dialog_content = "อืมมม แบบนั้นมากกว่า",
  str_homestory_N23dianying_90030201_80_dialog_content = "(... ฟังดูร้ายแรงถ้าฉันแสดงตัว ซ่อนไว้ดีที่สุด)",
  str_homestory_N23dianying_90030201_81_dialog_content = "มาดูวิธีการใช้กระจกวิเศษกันก่อน ฉันดูเหมือนจะจำตำนานที่บอกว่ากระจกสามารถตอบคำถามใด ๆ ?",
  str_homestory_N23dianying_90030201_82_dialog_content = "ดูเหมือนกระจกธรรมดาสำหรับฉัน",
  str_homestory_N23dianying_90030201_82X1_dialog_content = "ดูเหมือนกระจกธรรมดาสำหรับฉัน คุณคิดว่ามีสวิตช์หรืออะไร?",
  str_homestory_N23dianying_90030201_83_dialog_content = "ก็ตีไปก็ไม่ได้อะไร พวกคุณมีความคิดอะไรบ้าง?",
  str_homestory_N23dianying_90030201_83X1_dialog_content = "เราพบเศษไดอารี่ที่มีข้อมูลที่เกี่ยวข้องระหว่างทางหรือไม่? พวกคุณกำลังคิดอะไรอยู่?",
  str_homestory_N23dianying_90030201_84_dialog_content = "ไม่มีอะไร! ฉันสนใจแต่วิชายิงธนู",
  str_homestory_N23dianying_90030201_84X1_dialog_content = "ไม่มีอะไร! ฉันสนใจแค่การยิงธนูและเกมสงคราม",
  str_homestory_N23dianying_90030201_85_dialog_content = "ไม่มีอะไรที่นี่อย่างใดอย่างหนึ่ง ฉันสนใจแต่มาตรการการรักษาเท่านั้น เวทมนตร์อื่นทำให้ฉันสับสน",
  str_homestory_N23dianying_90030201_85X1_dialog_content = "ไม่มีอะไรที่นี่อย่างใดอย่างหนึ่ง ฉันแค่สนใจน้ำผึ้ง...เอ่อ ฉันหมายถึงการใช้น้ำผึ้งเพื่อการรักษา",
  str_homestory_N23dianying_90030201_86_dialog_content = "ไม่ใช่เรื่องบังเอิญ! ฉันเคยสนใจแต่การหั่นและหั่นมอนสเตอร์เท่านั้น แต่ตอนนี้ ความสนใจของฉันได้ขยายออกไปรวมถึงการหั่นและหั่นลูกเต๋าของคนแปลกหน้าที่น่าสงสัย",
  str_homestory_N23dianying_90030201_87_dialog_content = "(หือ? ไม่มีใครเรียนเวทมนตร์เลยเหรอ?)",
  str_homestory_N23dianying_90030201_88_dialog_content = "(นั่นอาจเป็นโอกาสของฉัน...)",
  str_homestory_N23dianying_90030201_89_dialog_content = "ฮะ?! มีใครซ่อนอยู่หลังกระจกวิเศษหรือไม่?",
  str_homestory_N23dianying_90030201_89X1_dialog_content = "ฮะ?! มีใครอยู่หลังกระจกวิเศษไหม? ศัตรูที่ซ่อนอยู่?",
  str_homestory_N23dianying_90030201_90_dialog_content = "ยินดีต้อนรับทุกคน!",
  str_homestory_N23dianying_90030201_91_dialog_content = "นักสำรวจผู้กล้าหาญ",
  str_homestory_N23dianying_90030201_92_dialog_content = "ว-คุณเป็นใคร? มาทำอะไรที่นี่?",
  str_homestory_N23dianying_90030201_92X1_dialog_content = "ว-คุณเป็นใคร? มาทำอะไรที่นี่? คุณเป็นศัตรูหรือไข่อีสเตอร์บางชนิดหรือไม่?",
  str_homestory_N23dianying_90030201_93_dialog_content = "ไม่ต้องกลัว.",
  str_homestory_N23dianying_90030201_94_dialog_content = "ไม่ต้องกังวล",
  str_homestory_N23dianying_90030201_95_dialog_content = "ฉันคือวิญญาณที่อยู่ภายในวัตถุนี้ จินนี่แห่งกระจกเงา",
  str_homestory_N23dianying_90030201_95X1_dialog_content = "เธอกำลังเข้าสู่มัน! ฮ่าๆๆๆ!",
  str_homestory_N23dianying_90030201_95X2_dialog_content = "น่าอายชะมัด ชับบ์!",
  str_homestory_N23dianying_90030201_95X3_dialog_content = "พวกเขาหมกมุ่นอยู่กับตัวละคร Chubb",
  str_homestory_N23dianying_90030201_96_dialog_content = "จินนี่แห่งกระจกเงา...? ฉันไม่คิดว่าฉันเคยได้ยินคุณพูดถึงในตำนาน",
  str_homestory_N23dianying_90030201_97_dialog_content = "ค่อนข้างถูกต้อง ค่อนข้างถูกต้อง แต่ตำนานก็เป็นเช่นนั้น มันไม่เหมือนกับว่ามีใครเคยเอา Frost Mirror มาจริงๆ เหรอ?",
  str_homestory_N23dianying_90030201_97X1_dialog_content = "ค่อนข้างถูกต้อง ค่อนข้างถูกต้อง แต่ตำนานก็เป็นเช่นนั้น ไม่เหมือนใครที่เคยเอา Frost Mirror มาจริงๆ",
  str_homestory_N23dianying_90030201_98_dialog_content = "แต่ทำไมมันพูดจาไพเราะเช่นนี้",
  str_homestory_N23dianying_90030201_98X1_dialog_content = "น้ำเสียงของผู้ชายคนนี้น่าสงสัยถ้าคุณถามฉัน",
  str_homestory_N23dianying_90030201_99_dialog_content = "นั่นคือ อ่า นั่นเป็นเพราะว่าฉันถูกผนึกอยู่ที่นี่มาเป็นเวลานาน ด้วยพลังเวทย์มนตร์ไม่เพียงพอ",
  str_homestory_N23dianying_90030201_100_dialog_content = "ฉันขอร้องคุณ พาฉันออกไปจากที่นี่ ออกไปจาก Frost Dragon! นำข้าพเจ้าไปสู่แดนไกลไร้คนอาศัย",
  str_homestory_N23dianying_90030201_101_dialog_content = "(หลังจากนั้นฉันจะแอบหนีไปกลางดึกด้วยกระจกวิเศษ ฮี่ฮี่...)",
  str_homestory_N23dianying_90030201_102_dialog_content = "อ้อเข้าใจแล้ว! งั้นเราไปกันเลยดีกว่า!",
  str_homestory_N23dianying_90030201_103_dialog_content = "รอสักครู่! แล้วธุรกิจที่ \"ไว้ใจคนอื่นง่ายเกินไป\" ล่ะ? อย่างน้อยขอความเห็นจาก Miss Healer ก่อน!",
  str_homestory_N23dianying_90030201_104_dialog_content = "จีนี่ตัวจริงน่าจะสาธิตพลังของกระจกให้เราได้นิดหน่อย นั่นก็เพียงพอแล้วที่จะพิสูจน์ข้อเรียกร้องของพวกเขา",
  str_homestory_N23dianying_90030201_104X1_dialog_content = "ขอคิดดูก่อน... โอ้!",
  str_homestory_N23dianying_90030201_104X2_dialog_content = "หา? อะไรเหรอ",
  str_homestory_N23dianying_90030201_104X3_dialog_content = "เวลาหายไปจากฉัน—ฉันต้องทำภารกิจที่ราชินีมอบให้ฉันให้เสร็จ! ฉันขอโทษผู้อำนวยการ!",
  str_homestory_N23dianying_90030201_104X4_dialog_content = "เอ๊ะ มันคืออะไร เราจะหาคนมาแทนที่",
  str_homestory_N23dianying_90030201_105_dialog_content = "(... นี่คือสิ่งที่คาดหวัง แต่ฉันพร้อมแล้ว)",
  str_homestory_N23dianying_90030201_106_dialog_content = "แต่แน่นอน.",
  str_homestory_N23dianying_90030201_107_dialog_content = "โปรดสังเกต—",
  str_homestory_N23dianying_90030201_108_dialog_content = "ให้มีแสงสว่าง!",
  str_homestory_N23dianying_90030201_109_dialog_content = "กระจกวิเศษ.",
  str_homestory_N23dianying_90030201_110_dialog_content = "(ม้วนเวทย์มนตร์ราคาแพงเหล่านั้นมีประโยชน์)",
  str_homestory_N23dianying_90030201_111_dialog_content = "ว้าว! มันตอบสนองจริงๆ!",
  str_homestory_N23dianying_90030201_112_dialog_content = "แน่นอนว่าคุณไม่สามารถแค่ปลาวาฬเหมือน \"ฮีโร่\" ดูเหมือนว่าจะต้องการให้ Genie of the Mirror ทำงาน",
  str_homestory_N23dianying_90030201_112X1_dialog_content = "แน่นอนว่าการเดาอย่างกล้าหาญจะไม่ได้ผล ดูเหมือนว่าเราต้องการความช่วยเหลือจาก Genie of the Mirror เพื่อใช้งาน",
  str_homestory_N23dianying_90030201_113_dialog_content = "โอ้... ฉันพนันได้เลยว่ามันจะใช้งานได้ดีอีกสองสามอย่าง!",
  str_homestory_N23dianying_90030201_113X1_dialog_content = "โอ้... ฉันพนันได้เลยว่ามันจะใช้งานได้ดีอีกสองสามอย่าง! เกมมากมายมีการออกแบบนี้!",
  str_homestory_N23dianying_90030201_114_dialog_content = "ฉันไม่แน่ใจว่าจะรักษากระจกวิเศษที่พังได้...",
  str_homestory_N23dianying_90030201_115_dialog_content = "ไม่เป็นไรสำหรับตอนนี้! ไปลองใช้ความสามารถในการตอบคำถาม!",
  str_homestory_N23dianying_90030201_116_dialog_content = "ก้าวขึ้นมาเลย Miss Healer!",
  str_homestory_N23dianying_90030201_117_dialog_content = "ตกลง! โอ้ กระจกวิเศษ กระจกวิเศษ... อะไรคือจุดสุดยอดของความสำเร็จในการรักษาของฉัน?",
  str_homestory_N23dianying_90030201_118_dialog_content = "นั่นเป็นวิธีที่จะถามใช่มั้ย?",
  str_homestory_N23dianying_90030201_119_dialog_content = "แป๊บนึง-",
  str_homestory_N23dianying_90030201_120_dialog_content = "คำตอบกำลังเกิดขึ้น",
  str_homestory_N23dianying_90030201_121_dialog_content = "คุณจะได้รับชื่อเสียงและโชคลาภจากการรักษาถ้ำของคุณ ตกลงไปในห้วงนิทราจากอาการป่วยของเขา",
  str_homestory_N23dianying_90030201_122_dialog_content = "แต่ความสำเร็จที่ยิ่งใหญ่ที่สุดและสุดท้ายของคุณคือการรักษา Demon King of narcolepsy และมอบพลังอันไร้ขอบเขตให้กับเขา",
  str_homestory_N23dianying_90030201_123_dialog_content = "สิ่งนี้มีผลข้างเคียงที่โชคร้ายที่ทำให้เขายังคงตื่นอยู่ชั่วนิรันดร์ และด้วยความโกรธแค้นและพลังที่ล้นเกินของเขา เขาทำลายโลกทั้งใบ",
  str_homestory_N23dianying_90030201_123X1_dialog_content = "ไปข้างหน้าทำสิ่งต่างๆขึ้น",
  str_homestory_N23dianying_90030201_123X2_dialog_content = "พวกเขาด้นสดหรือไม่? ชับบ์.",
  str_homestory_N23dianying_90030201_123X3_dialog_content = "ไม่มีใครจะเชื่ออย่างนั้น ชับบ์!",
  str_homestory_N23dianying_90030201_124_dialog_content = "...",
  str_homestory_N23dianying_90030201_125_dialog_content = "T-The Magic Mirror ไม่ได้แม่นยำเสมอไปใช่ไหม? ไม่จำเป็นต้องเชื่อทุกคำ",
  str_homestory_N23dianying_90030201_126_dialog_content = "จริงๆ แล้ว... ฉันมีพลังพอที่จะปลุก Demon King ขึ้นมาได้??",
  str_homestory_N23dianying_90030201_127_dialog_content = "อิ ๆ ๆ ๆ...",
  str_homestory_N23dianying_90030201_128_dialog_content = "ไม่ตลกนะ มิสฮีลเลอร์! คุณกำลังทำให้ฉันประหลาดใจ",
  str_homestory_N23dianying_90030201_129_dialog_content = "ไม่ต้องห่วงฉัน! ตาของอาร์เชอร์!",
  str_homestory_N23dianying_90030201_130_dialog_content = "มะ ฉันไม่ยุ่ง ฉันไม่สนใจเรื่องทั้งหมดนี้ด้วยซ้ำ",
  str_homestory_N23dianying_90030201_131_dialog_content = "ปล่อยให้ฮีโร่ไปต่อ",
  str_homestory_N23dianying_90030201_132_dialog_content = "แน่นอน! กระจกวิเศษ กระจกวิเศษ บอกฉันทีว่าฉันจะแข็งแกร่งแค่ไหน!",
  str_homestory_N23dianying_90030201_133_dialog_content = "คุณ... คุณจะละทิ้งตำแหน่งของคุณในฐานะฮีโร่แห่งแสง และตกหลุมรักสิ่งมีชีวิตตัวน้อยที่คุณพบในการผจญภัยของคุณ",
  str_homestory_N23dianying_90030201_133X1_dialog_content = "คุณ... คุณจะละทิ้งตำแหน่งของคุณในฐานะฮีโร่แห่งแสง และเริ่มศึกษา \"Magimechs\" ซึ่งเป็นหุ่นยนต์ยักษ์ประเภทหนึ่ง",
  str_homestory_N23dianying_90030201_134_dialog_content = "จากนั้นคุณจะร่วมมือกับพวกเขาเพื่อกำจัดศัตรู Gym Leader ทั้งหมดของคุณทีละตัว",
  str_homestory_N23dianying_90030201_134X1_dialog_content = "แต่หุ่นยนต์เหล่านั้นซึ่งเดิมสร้างขึ้นเพื่อปกป้องผู้คน เริ่มตระหนักรู้ในตนเองและเริ่มโจมตีผู้คนแทน",
  str_homestory_N23dianying_90030201_135_dialog_content = "แต่คุณจะ... ไม่เคยเป็นแชมป์ และในที่สุดก็พินาศด้วยความอัปยศอดสู",
  str_homestory_N23dianying_90030201_135X1_dialog_content = "และคุณจะได้เริ่มภารกิจกับเพื่อนหุ่นยนต์เพียงคนเดียวของคุณ เพื่อค้นหาความจริงเบื้องหลังการจลาจลของ Magimech",
  str_homestory_N23dianying_90030201_135A1_dialog_content = "มันไร้สาระมากขึ้นเรื่อยๆ ชับบ์",
  str_homestory_N23dianying_90030201_135A2_dialog_content = "ฟังดูคุ้นเคย?",
  str_homestory_N23dianying_90030201_135A3_dialog_content = "มันน่าสนใจอย่างลึกลับ?",
  str_homestory_N23dianying_90030201_136_dialog_content = "มีโอกาสแค่ไหน...",
  str_homestory_N23dianying_90030201_137_dialog_content = "กระจกวิเศษไร้สาระ! กล้าดียังไงมาใส่ร้ายฮีโร่ที่รักของฉัน!",
  str_homestory_N23dianying_90030201_137X1_dialog_content = "คุณเอาแต่พูดเรื่องไร้สาระไปเรื่อย มิเรอร์! กล้าดียังไงมาใส่ร้ายฮีโร่ผู้ยิ่งใหญ่ของเรา!!",
  str_homestory_N23dianying_90030201_138_dialog_content = "ฮะ? รอ! รอสักครู่!",
  str_homestory_N23dianying_90030201_139_dialog_content = "นั่นคือความสัมพันธ์ของคุณ—!",
  str_homestory_N23dianying_90030201_139X1_dialog_content = "ใจเย็นก่อนนะ!",
  str_homestory_N23dianying_90030201_140_dialog_content = "<color=#e8d9bb>ปัง—!</color>",
  str_homestory_N23dianying_90030201_141_dialog_content = "เฮ้ คุณกำลังทำอะไร หากคุณสร้างความเสียหายให้กับกระจกวิเศษ Genie อาจได้รับบาดเจ็บหรือเสียชีวิตได้!",
  str_homestory_N23dianying_90030201_142_dialog_content = "ดูท่าทีเจ็บปวดของเธอสิ!",
  str_homestory_N23dianying_90030201_143_dialog_content = "เจ็บปวด... การแสดงออก?",
  str_homestory_N23dianying_90030201_144_option_content = "ทรุด",
  str_homestory_N23dianying_90030201_145_dialog_content = "ถอยไป บาร์บาโตส! “ทำเสียงเจ็บปวดและทรุดตัวลง!”",
  str_homestory_N23dianying_90030201_146_dialog_content = "โอ้โห...",
  str_homestory_N23dianying_90030201_147_dialog_content = "... โอ้! ความทุกข์ทรมานเช่นนี้!",
  str_homestory_N23dianying_90030201_148_dialog_content = "ฉันได้รับบาดเจ็บ—",
  str_homestory_N23dianying_90030201_149_dialog_content = "ฉันขอโทษ... ฉันหุนหันพลันแล่นเกินไป...",
  str_homestory_N23dianying_90030201_149X1_dialog_content = "ฉันขอโทษ... นี่คือความโง่เขลาของเยาวชน",
  str_homestory_N23dianying_90030201_150_dialog_content = "ฉันขอรบกวนคุณลองหน่อยได้ไหม Miss Healer?",
  str_homestory_N23dianying_90030201_151_dialog_content = "ฉันจะลองดู... ถ้าเพียงแต่จะกวนหม้อเล็กน้อย! ฉันคือผู้ที่สามารถรักษาราชาปีศาจได้!",
  str_homestory_N23dianying_90030201_152_dialog_content = "คุณจะไม่ปล่อยให้ใครลืมว่าในเร็ว ๆ นี้ใช่ไหม?",
  str_homestory_N23dianying_90030201_153_dialog_content = "อืม เห็นได้ชัดว่าเป็นกระจกวิเศษ แต่ทำไมมันถึงเสียหายง่ายจัง?",
  str_homestory_N23dianying_90030201_154_dialog_content = "ฝีมือห่วย.",
  str_homestory_N23dianying_90030201_155_dialog_content = "II สัมผัสพลังแห่งการรักษา",
  str_homestory_N23dianying_90030201_156_dialog_content = "ฉัน จินนี่แห่งกระจกเงา ฟื้นแล้ว!",
  str_homestory_N23dianying_90030201_157_dialog_content = "ยอดเยี่ยม! และ เอ่อ คำขอโทษของเรา",
  str_homestory_N23dianying_90030201_157X1_dialog_content = "ยอดเยี่ยม! และเอ่อ ขอโทษด้วย",
  str_homestory_N23dianying_90030201_158_dialog_content = "บางครั้งนักธนูก็ใจร้อนมากกว่าฉัน แต่นอกจากข้อบกพร่องเล็กๆ น้อยๆ นี้แล้ว เธอก็มีจิตใจที่ดี",
  str_homestory_N23dianying_90030201_159_dialog_content = "สองคนนั้นตั้งแต่เมื่อไหร่...",
  str_homestory_N23dianying_90030201_160_dialog_content = "ฮ่าๆๆๆ—",
  str_homestory_N23dianying_90030201_161_dialog_content = "มาจากข้างนอกเหรอ!",
  str_homestory_N23dianying_90030201_162_dialog_content = "มันคือมังกรน้ำแข็ง!",
  str_homestory_N23dianying_90030201_163_dialog_content = "ปัญญาอ่อน! เจ้าคิดว่าจะฆ่าข้าได้จริงหรือ?",
  str_homestory_N23dianying_90030201_164_dialog_content = "คุณพลาดโอกาสที่จะเอาชนะฉันแล้ว และตอนนี้ฉันกำลังจากไป—และนำ Frost Mirror ไปด้วย!",
  str_homestory_N23dianying_90030201_165_dialog_content = "ขจัดความโง่เขลาของคุณไปตลอดชีวิต! ฮ่า ๆ ๆ ๆ-",
  str_homestory_N23dianying_90030201_166_dialog_content = "...",
  str_homestory_N23dianying_90030201_167_dialog_content = "...",
  str_homestory_N23dianying_90030201_168_dialog_content = "...",
  str_homestory_N23dianying_90030201_169_dialog_content = "มังกรใบ้นั่นพูดว่าอะไรนะ??",
  str_homestory_N23dianying_90030201_170_dialog_content = "ไม่ได้สังเกตว่าเรามี Frost Mirror แล้ว",
  str_homestory_N23dianying_90030201_170X1_dialog_content = "ตัวตลกใหญ่อะไรอย่างนี้! เรามี Frost Mirror แล้ว ฮ่าฮ่าฮ่า!",
  str_homestory_N23dianying_90030201_171_dialog_content = "แต่ตอนนี้เรารู้แล้วว่า Frost Dragon ไล่ตามกระจกเงา เราต้องคอยเฝ้าระวังและจับตาดูอยู่ตลอดเวลา",
  str_homestory_N23dianying_90030201_172_dialog_content = "ไม่ต้องกังวล. เราจะปกป้องคุณ",
  str_homestory_N23dianying_90030201_173_dialog_content = "... ใช่ ๆ. ดี. คุณพูดถูก",
  str_homestory_N23dianying_90030201_174_dialog_content = "จริงๆ ฉันรู้สึกขอบคุณคุณมาก",
  str_homestory_N23dianying_90030201_175_option_content = "รู้สึกว่าบางอย่างไม่ถูกต้อง",
  str_homestory_N23dianying_90030201_176_dialog_content = "อาร์เชอร์ คุณรู้สึกว่ามีบางอย่างผิดปกติ “นายนี่น่าสงสัยจริงๆ”",
  str_homestory_N23dianying_90030201_177_dialog_content = "แม้ว่ากระจกที่คุณควรจะอาศัยอยู่นั้นถูกโจมตีอย่างชัดเจน แต่ดูเหมือนคุณจะไม่ตอบสนอง มันไม่แปลกเหรอ?",
  str_homestory_N23dianying_90030201_177X1_dialog_content = "แม้ว่ากระจกที่คุณควรจะอาศัยอยู่นั้นถูกโจมตีอย่างชัดเจน แต่ดูเหมือนคุณจะไม่ตอบสนอง มันค่อนข้างแปลกจริงๆ",
  str_homestory_N23dianying_90030201_178_dialog_content = "อะไร จะบอกว่าคนนี้...",
  str_homestory_N23dianying_90030201_178X1_dialog_content = "อะไร คุณหมายถึง—คุณกำลังพูดว่าผู้ชายคนนี้ไม่ใช่ไข่อีสเตอร์เลยเหรอ?",
  str_homestory_N23dianying_90030201_179_dialog_content = "รอเดี๋ยวรอสักครู่! ฉันอธิบายได้—ฉันเจ็บปวด เจ็บปวดมากจนคิดว่าฉันจะเป็นลม!",
  str_homestory_N23dianying_90030201_180_dialog_content = "ฉันอธิบายได้! ได้โปรด แค่ฟัง",
  str_homestory_N23dianying_90030201_181_dialog_content = "ฮ่าๆๆๆ—",
  str_homestory_N23dianying_90030201_182_dialog_content = "มาจากข้างนอกเหรอ!",
  str_homestory_N23dianying_90030201_183_dialog_content = "มันคือมังกรน้ำแข็ง!",
  str_homestory_N23dianying_90030201_184_dialog_content = "ปัญญาอ่อน! เจ้าคิดว่าจะฆ่าข้าได้จริงหรือ?",
  str_homestory_N23dianying_90030201_185_dialog_content = "คุณพลาดโอกาสที่จะเอาชนะฉันแล้ว และตอนนี้ฉันกำลังจากไป—และนำ Frost Mirror ไปด้วย!",
  str_homestory_N23dianying_90030201_186_dialog_content = "ขจัดความโง่เขลาของคุณไปตลอดชีวิต! ฮ่า ๆ ๆ ๆ-",
  str_homestory_N23dianying_90030201_187_dialog_content = "ไม่มีการให้อภัย—",
  str_homestory_N23dianying_90030201_188_option_content = "สำนึกทันใด",
  str_homestory_N23dianying_90030201_189_dialog_content = "ฮีโร่ จู่ๆ คุณก็ได้ตระหนักถึงบางสิ่งที่สำคัญ “ดาบหายไปแล้ว”",
  str_homestory_N23dianying_90030201_190_dialog_content = "ถือขึ้นลืมเรื่องนี้สักครู่ มันเป็นแค่ฉันหรือดาบหายไป?",
  str_homestory_N23dianying_90030201_191_dialog_content = "ไม่มีทาง... มันยังติดอยู่ในหัวของ Frost Dragon ไม่ได้ใช่ไหม",
  str_homestory_N23dianying_90030201_192_dialog_content = "รีบกลับไปค้นหากันเถอะ! เรากำลังมีปัญหาใหญ่ถ้าฮีโร่ทำดาบหาย!",
  str_homestory_N23dianying_90030201_193_dialog_content = "โอ้? อืม... มาอีกไหม",
  str_homestory_N23dianying_90030201_194_dialog_content = "ฮะ? คนนี้เป็นใคร?",
  str_homestory_N23dianying_90030201_194X1_dialog_content = "ฮะ? คนนี้เป็นใคร? NPC เบื้องหลัง?",
  str_homestory_N23dianying_90030201_195_dialog_content = "ลืมเธอไปเลย เราต้องมองหากระจก",
  str_homestory_N23dianying_90030201_195X1_dialog_content = "ลืมเธอไปเลย เราต้องมองหากระจก ฉันยังมีสิ่งที่ต้องทำในภายหลัง",
  str_homestory_N23dianying_90030201_196_dialog_content = "หืมม?",
  str_homestory_N23dianying_90030201_197_dialog_content = "ว่าไง",
  str_homestory_N23dianying_90030201_198_dialog_content = "ทำไมไม่มีร่องรอยของกระจกวิเศษ?",
  str_homestory_N23dianying_90030201_198X1_dialog_content = "ทำไมไม่มีร่องรอยของกระจกวิเศษ? เรายังไม่ได้ทำเครื่องหมายในช่องใด ๆ โดยพลการ ??",
  str_homestory_N23dianying_90030201_199_dialog_content = "คุณคิดว่าผู้ชายคนนี้ขโมยมัน?",
  str_homestory_N23dianying_90030201_200_dialog_content = "อะไร?! ฉันแค่จะถามคุณว่า",
  str_homestory_N23dianying_90030201_201_dialog_content = "มันไม่สนุกเลยที่แอบเข้ามาที่นี่ และฉันต้องมีกระจกเงานั้นเพื่อที่จะได้เป็นพ่อค้าที่ร่ำรวยที่สุดในโลก",
  str_homestory_N23dianying_90030201_202_dialog_content = "แอบเข้ามา? คุณไม่คิดว่า—ผู้ชายคนนี้เป็นขโมยหรือเปล่า?",
  str_homestory_N23dianying_90030201_203_dialog_content = "นั่นเป็นสิ่งที่เรียกจริงๆ",
  str_homestory_N23dianying_90030201_203X1_dialog_content = "ที่นำความทรงจำที่น่ารังเกียจบางอย่างกลับมา ฉันต้องสอนบทเรียนให้คุณ",
  str_homestory_N23dianying_90030201_204_dialog_content = "ฮ่าๆๆๆ—",
  str_homestory_N23dianying_90030201_205_dialog_content = "มาจากข้างนอกเหรอ!",
  str_homestory_N23dianying_90030201_206_dialog_content = "มันคือมังกรน้ำแข็ง!",
  str_homestory_N23dianying_90030201_207_dialog_content = "ปัญญาอ่อน! เจ้าคิดว่าจะเอาชนะข้าได้จริงหรือ?",
  str_homestory_N23dianying_90030201_208_dialog_content = "ตอนนี้ ฉันกำลังจะไป และฉันจะเอา Frost Mirror ไปด้วย! อีกอย่าง... ที่แห่งนี้กำลังจะพังทลายลงทุกวินาทีเลย ดังนั้นจงขจัดความโง่เขลาของคุณไปตลอดชีวิตอันแสนสั้นของคุณ! ฮ่า ๆ ๆ ๆ-",
  str_homestory_N23dianying_90030201_209_dialog_content = "แดร็ก มังกรหนีไปแล้ว",
  str_homestory_N23dianying_90030201_210_dialog_content = "ไล่ตามมันเดี๋ยวนี้!",
  str_homestory_N23dianying_90030201_210X1_dialog_content = "รีบตามไปนะทุกคน! ฉัน เอ่อ ฉันจะไปทำภารกิจที่ราชินีมอบให้ฉันให้เสร็จ!",
  str_homestory_N23dianying_90030201_211_dialog_content = "เอ่อ? เฮ้! รอฉันด้วย!",
  str_homestory_N23dianying_90030201_211X1_dialog_content = "ตอนจบนี้แซ่บมาก! ชับบ์!",
  str_homestory_N23dianying_90030201_212_dialog_content = "ฉันไม่สามารถพูดได้ว่ามันเป็นเพียงธรรมชาติที่ยอดเยี่ยมของคุณหรือการแสดงที่ยอดเยี่ยม แต่การล่มสลายแบบนั้นเป็นจังหวะของอัจฉริยะชับบ์",
  str_homestory_N23dianying_90030201_213_dialog_content = "Heyyyy ตอนนี้รู้สึกได้ถึงบางสิ่งที่ยังไม่ถูกต้อง? นั่นเป็นพล็อตเรื่องหักมุมเล็กน้อย ชับบ์!",
  str_homestory_N23dianying_90030201_214_dialog_content = "ทำไมคุณไม่อธิบายมัน ต่อไป!",
  str_homestory_N23dianying_90030201_215_dialog_content = "ในภาพยนตร์และรายการโทรทัศน์ส่วนใหญ่ ยิ่งคุณอยากรู้มากเท่าไหร่ ชับบ์ก็ยิ่งเพิ่มความสงสัยมากขึ้นเท่านั้น",
  str_homestory_N23dianying_90030201_216_dialog_content = "Frost Dragon ค่อนข้างจะบินไปกับมันแล้ว!",
  str_homestory_N23dianying_90030201_217_dialog_content = "แต่ดาบไม่ใช่แม้แต่อุปกรณ์ประกอบฉากใช่ไหม? เกิดอะไรขึ้นกับโครงเรื่อง ชับบ์?",
  str_homestory_N23dianying_90030301_1_dialog_content = "วุ้ย อาจต้องใช้เวลาสองวัน แต่อย่างน้อยทุกอย่างก็มารวมกัน",
  str_homestory_N23dianying_90030301_2_dialog_content = "พวกอันธพาลบ้าๆ บอๆ ทำลายสถานที่ที่มีศิลปะแบบนี้",
  str_homestory_N23dianying_90030301_3_dialog_content = "แต่โชคดีที่เปียโนรอดมาได้ค่อนข้างปลอดภัย...",
  str_homestory_N23dianying_90030301_3X1_dialog_content = "ดูแพงนะชับบ์",
  str_homestory_N23dianying_90030301_4_dialog_content = "แต่โชคดีที่นี่คือโอกาสที่จะเกลี้ยกล่อมเจ้านายให้เปลี่ยนเปียโนเป็นเวที",
  str_homestory_N23dianying_90030301_5_dialog_content = "ต่อจากนี้ไปก็ร้องได้ตามใจ...",
  str_homestory_N23dianying_90030301_5X1_dialog_content = "อยากลดเสียง Chubb...",
  str_homestory_N23dianying_90030301_6_dialog_content = "ไม่น่าเชื่อว่าเจ้านายจะขี้หึงขนาดนี้",
  str_homestory_N23dianying_90030301_7_dialog_content = "ไม่ยอมจ่ายค่าซ่อมเปียโนหลังได้รับความเสียหาย",
  str_homestory_N23dianying_90030301_8_dialog_content = "และส่งข้าไปที่โกดังเก่าเพื่อประดับประดาโบราณ...",
  str_homestory_N23dianying_90030301_8X1_dialog_content = "สิ่งนี้คืออะไร?",
  str_homestory_N23dianying_90030301_9_dialog_content = "<color=#e8d9bb>ดิง—</color>",
  str_homestory_N23dianying_90030301_10_dialog_content = "ฉันขอโทษ แต่เราปิด—",
  str_homestory_N23dianying_90030301_11_dialog_content = "ฮะ? อีกแล้วเหรอ!",
  str_homestory_N23dianying_90030301_12_dialog_content = "ตอนนี้ตอนนี้ นั่นไม่มีทางต้อนรับลูกค้าได้หรอก คุณบาร์เทนเดอร์",
  str_homestory_N23dianying_90030301_12X1_dialog_content = "เจอกันอีกแล้วนะบาร์เทนเดอร์",
  str_homestory_N23dianying_90030301_13_dialog_content = "วันนี้ฉันมีเรื่องเร่งด่วนที่จะปรึกษากับเพื่อนเก่า ดังนั้น Umbraton Encounter สองแก้ว ถ้าคุณใจดี",
  str_homestory_N23dianying_90030301_13X1_dialog_content = "วันนี้ฉันพาเพื่อนเก่ามาที่นี่เพื่อคุยเรื่องธุรกิจ ดังนั้นขอ Rediesel Special สองแก้ว",
  str_homestory_N23dianying_90030301_14_dialog_content = "ออกสดๆ. เสียใจ.",
  str_homestory_N23dianying_90030301_15_dialog_content = "คุณสามารถขอบคุณคนบ้าที่มาที่นี่เมื่อสองสามวันก่อนและทุบสถานที่นี้!",
  str_homestory_N23dianying_90030301_16_dialog_content = "โอ้ น่าเสียดายจัง ดูเหมือนว่าฉันจะให้เครื่องดื่มแก่คุณในโอกาสนี้ไม่ได้",
  str_homestory_N23dianying_90030301_16X1_dialog_content = "โอ้ถูกต้อง มีว่า... เหตุการณ์ที่เกิดขึ้น",
  str_homestory_N23dianying_90030301_17_dialog_content = "คุณอยู่ที่นั่นเมื่อมันเกิดขึ้น! อย่าเล่นไร้เดียงสากับฉัน!",
  str_homestory_N23dianying_90030301_17X1_dialog_content = "เราไปลองที่อื่นกันดีไหม?",
  str_homestory_N23dianying_90030301_18_dialog_content = "ทุกอย่างปกติดี. เรากำลังจะหมดสัญญาอยู่ดี มาทำให้มันเสร็จกันเถอะ",
  str_homestory_N23dianying_90030301_19_dialog_content = "อีกอย่าง คุณขอให้บาร์เทนเดอร์เปลี่ยนเพลงให้มากกว่านี้หน่อยได้ไหม...",
  str_homestory_N23dianying_90030301_20_dialog_content = "การเลือกเพลงของคุณทำให้เป็นที่ต้องการอย่างมาก",
  str_homestory_N23dianying_90030301_21_dialog_content = "เธอว่าไงนะ",
  str_homestory_N23dianying_90030301_22_dialog_content = "สถานที่ทั้งหมดนี้ต้องการการปรับปรุงจริงๆ",
  str_homestory_N23dianying_90030301_23_dialog_content = "เธอว่าไงนะ",
  str_homestory_N23dianying_90030301_24_dialog_content = "ฉันมีพวกคุณต่อสู้ที่นี่เพื่อขอบคุณสำหรับสิ่งนั้นเช่นกัน",
  str_homestory_N23dianying_90030301_25_dialog_content = "ทำลายการตกแต่งก่อนหน้านี้ทั้งหมดและทุบเฟอร์นิเจอร์!",
  str_homestory_N23dianying_90030301_26_dialog_content = "ดี. ให้ฉันกลับไปหาคุณเกี่ยวกับเรื่องนั้นในภายหลัง",
  str_homestory_N23dianying_90030301_27_dialog_content = "การตกแต่งที่นี่น้อย...ก็สวยแย่",
  str_homestory_N23dianying_90030301_28_dialog_content = "ฉันไม่ต้องการที่จะอยู่ที่นี่เป็นวินาทีนานกว่าความจำเป็นอย่างยิ่ง",
  str_homestory_N23dianying_90030301_29_dialog_content = "ขอบาร์เทนเดอร์เปลี่ยนเรคคอร์ดหน่อยเถอะ",
  str_homestory_N23dianying_90030301_29X1_dialog_content = "ฮ่าฮ่าฮ่า! ได้โปรดอย่าสนใจเพื่อนของฉัน เขาพูดได้แค่นี้",
  str_homestory_N23dianying_90030301_30_dialog_content = "เราเป็นเพื่อนที่ดีกับเจ้านายที่นี่ ฉันแน่ใจว่าเขาจะไม่เป็นไร",
  str_homestory_N23dianying_90030301_30X1_dialog_content = "ฉันเป็นเพื่อนที่ดีกับเจ้านายของคุณ เขาจะไม่พูดอะไรถ้าฉันใช้พื้นที่เล็กน้อยที่นี่",
  str_homestory_N23dianying_90030301_30X2_dialog_content = "ฉันจะอธิบายทั้งหมดให้เขาฟังในภายหลัง คุณเพียงแค่กระโดดตามและเปลี่ยนเพลง",
  str_homestory_N23dianying_90030301_31_dialog_content = "เอ่อ... บอส?",
  str_homestory_N23dianying_90030301_32_dialog_content = "... ดี. ฉันเข้าใจแล้ว.",
  str_homestory_N23dianying_90030301_33_dialog_content = "แดรท. ใช้เจ้านายตัวเองข่มขู่ฉัน",
  str_homestory_N23dianying_90030301_34_dialog_content = "สถานที่แห่งนี้จะไม่มีอะไรนอกจากการแฮงค์เอาท์ของแก๊งค์ในอัตรานี้",
  str_homestory_N23dianying_90030301_35_dialog_content = "ฉันต้องคิดหาวิธีหยุดพวกเขาไม่ให้มาอีก",
  str_homestory_N23dianying_90030301_36_dialog_content = "ฉันรู้! เมื่อเห็นว่าสุภาพบุรุษที่สง่างามที่สุดคนนี้ชอบสภาพแวดล้อมที่หายากของเขา ฉันมีบันทึก—",
  str_homestory_N23dianying_90030301_37_dialog_content = "ฉันขอโทษ นี่ไม่ใช่สิ่งที่เราตกลงกัน ฉันไม่สามารถ—",
  str_homestory_N23dianying_90030301_38_dialog_content = "ฮะ? มีอะไรเข้าไปในบาร์เทนเดอร์? เพลงนี้—",
  str_homestory_N23dianying_90030301_38X1_dialog_content = "ฉันร้อนรุ่มไปหมด ชับบ์",
  str_homestory_N23dianying_90030301_39_dialog_content = "ฉันจะให้เขาปิดเครื่อง",
  str_homestory_N23dianying_90030301_39X1_dialog_content = "ว้าว เด็กคนนี้เล่นบางอย่างที่ฉันชอบจริงๆ",
  str_homestory_N23dianying_90030301_39X2_dialog_content = "แต่มันอาจจะดังไปหน่อยสำหรับคุณ ฉันจะให้เขาปิดเครื่อง",
  str_homestory_N23dianying_90030301_40_dialog_content = "ไม่เป็นไร",
  str_homestory_N23dianying_90030301_41_dialog_content = "ท่วงทำนองและจังหวะ... ทำให้นึกถึงตอนที่เราเคยแสดงด้วยกันในทัวร์",
  str_homestory_N23dianying_90030301_42_dialog_content = "เรามาย้อนอดีตกันมั้ย ชับบ์?!",
  str_homestory_N23dianying_90030301_43_dialog_content = "คุณจึงจำวันเหล่านั้นได้",
  str_homestory_N23dianying_90030301_44_dialog_content = "ฉันรู้ว่าเส้นทางของเราแตกต่างไปตามกาลเวลา เนื่องจากเรารับหน้าที่ที่แตกต่างกัน",
  str_homestory_N23dianying_90030301_45_dialog_content = "แม้ว่าฉันจะเข้าใจจุดยืนที่แตกต่างกันของเรา แต่ฉันก็ยังมีอารมณ์ในบางครั้ง",
  str_homestory_N23dianying_90030301_46_dialog_content = "ฉันก็เหมือนกัน",
  str_homestory_N23dianying_90030301_47_dialog_content = "... คุณรู้อะไรไหม? ให้ฉันกลับไปและพยายามทำให้สิ่งต่าง ๆ เคลื่อนไหวตามสัญญา",
  str_homestory_N23dianying_90030301_47X1_dialog_content = "... และเวลาที่ Rediesel Wrenches ของคุณปล้นสินค้าของเรา",
  str_homestory_N23dianying_90030301_47X2_dialog_content = "อย่าลืมเวลาที่ Shadowlord ส่งฉันมาหลังจากคุณ และฉันไล่ตามคุณผ่านทะเลทราย Rediesel เป็นเวลาสามวันเต็ม!",
  str_homestory_N23dianying_90030301_47X3_dialog_content = "เฮ้ เอาล่ะ! เราไม่ได้ตั้งใจจะทำหนังเหรอ? เกิดอะไรขึ้นกับความจริงจังในทันใด?",
  str_homestory_N23dianying_90030301_47X4_dialog_content = "... เสียใจ. ฉันแค่เห็นสีแดงทุกครั้งที่ฉันต้องมองหน้าเขา",
  str_homestory_N23dianying_90030301_47X5_dialog_content = "สคริปอยู่ไหน?",
  str_homestory_N23dianying_90030301_47X6_dialog_content = "ทำไมส่วนนี้ไม่ตัด ชับบ์!",
  str_homestory_N23dianying_90030301_47X7_dialog_content = "โอ้ ใช่ แล้วฉันจะกลับไปและพยายามทำให้สิ่งต่าง ๆ เคลื่อนไหวตามสัญญาได้อย่างไร",
  str_homestory_N23dianying_90030301_48_dialog_content = "มองว่าเป็นการช่วยเพื่อนเก่าออกไป",
  str_homestory_N23dianying_90030301_49_dialog_content = "ง่ายขนาดนั้นเชียว ชับบ์?",
  str_homestory_N23dianying_90030301_50_dialog_content = "ดีฉันรู้สึกขอบคุณจริงๆ",
  str_homestory_N23dianying_90030301_51_dialog_content = "ว้าว ฉันไม่เคยรู้มาก่อนเลยว่าคุณเก่งในการอ่านห้องมากขนาดนี้! ขอขอบคุณสำหรับความสำเร็จของการเจรจาเหล่านี้!",
  str_homestory_N23dianying_90030301_52_dialog_content = "คุณต้องรู้จักวง Rockin' Dragons วงเก่าของเราก่อนที่จะเลือกอัลบั้มนั้นใช่ไหม",
  str_homestory_N23dianying_90030301_52X1_dialog_content = "โอ้จริงเหรอ? ขอบคุณมาก!",
  str_homestory_N23dianying_90030301_52X2_dialog_content = "ว้าว ฉันไม่เคยรู้มาก่อนเลยว่าคุณเก่งในการอ่านห้องมากขนาดนี้! ขอขอบคุณสำหรับความสำเร็จของการเจรจาเหล่านี้!",
  str_homestory_N23dianying_90030301_52X3_dialog_content = "คุณต้องรู้จักวง Rockin' Dragons วงเก่าของเราก่อนที่จะเลือกอัลบั้มนั้นใช่ไหม",
  str_homestory_N23dianying_90030301_53_dialog_content = "ชู! ช่างเป็นความเข้าใจผิดอย่างมหันต์ ชับบ์!",
  str_homestory_N23dianying_90030301_54_dialog_content = "ฉันไม่-",
  str_homestory_N23dianying_90030301_55_dialog_content = "เมื่อเห็นว่าบาร์เทนเดอร์พิสูจน์ตัวเองได้อย่างน่าเชื่อถือ ฉันขออีกได้ไหม",
  str_homestory_N23dianying_90030301_56_dialog_content = "ฉันมีข้อความที่เป็นความลับและสำคัญมากที่นี่ ตัวกลางจะพร้อมรับในภายหลัง",
  str_homestory_N23dianying_90030301_56X1_dialog_content = "เห็นได้ชัดว่าทำไมเจ้านายถึงเลือกคุณมาจัดการที่นี่ การทำงานที่ดี!",
  str_homestory_N23dianying_90030301_56X2_dialog_content = "เมื่อเห็นว่าบาร์เทนเดอร์พิสูจน์ตัวเองได้อย่างน่าเชื่อถือ ฉันขออีกได้ไหม",
  str_homestory_N23dianying_90030301_56X3_dialog_content = "ฉันมีข้อความที่เป็นความลับและสำคัญมากที่นี่ ตัวกลางจะพร้อมรับในภายหลัง",
  str_homestory_N23dianying_90030301_57_dialog_content = "เดี๋ยวก่อน ฉันไม่—",
  str_homestory_N23dianying_90030301_58_dialog_content = "ไม่ต้องกังวล! มันง่ายมากจริงๆ",
  str_homestory_N23dianying_90030301_59_dialog_content = "ผู้ติดต่อจะใช้รหัสคำว่า \"ความงามใต้ดวงจันทร์\" เพียงแค่ส่งจดหมายเมื่อคุณได้ยินว่า",
  str_homestory_N23dianying_90030301_60_dialog_content = "ฉันมีธุระต้องไปทำอย่างอื่น ฉันจะลาไป",
  str_homestory_N23dianying_90030301_60X1_dialog_content = "ไม่ต้องกังวล! มันง่ายมากจริงๆ",
  str_homestory_N23dianying_90030301_60X2_dialog_content = "ผู้ติดต่อจะใช้รหัสคำว่า \"ความงามใต้ดวงจันทร์\" เพียงแค่ส่งจดหมายเมื่อคุณได้ยินว่า",
  str_homestory_N23dianying_90030301_60X3_dialog_content = "ฉันยังมีเรื่องสำคัญที่ต้องดูแล ดังนั้นฉันจะลาไป",
  str_homestory_N23dianying_90030301_61_dialog_content = "เฮ้! ฉันยังไม่เสร็จ!",
  str_homestory_N23dianying_90030301_62_dialog_content = "ให้คนจบ ชับบ์!",
  str_homestory_N23dianying_90030301_63_dialog_content = "จริงๆ...ไอ้พวกนี้แต่ละคน...",
  str_homestory_N23dianying_90030301_64_dialog_content = "<color=#e8d9bb>ดิง—</color>",
  str_homestory_N23dianying_90030301_65_dialog_content = "ตอนนี้เป็นใคร! พวกเขาไม่เห็นป้าย \"CLOSED\" ที่ประตูเหรอ?",
  str_homestory_N23dianying_90030301_66_dialog_content = "นายอำเภอเรียก! ขอโทษที่ขัดจังหวะ แต่ฉันมาที่นี่เกี่ยวกับการต่อสู้ที่เกิดขึ้นเมื่อสองสามวันก่อน",
  str_homestory_N23dianying_90030301_66X1_dialog_content = "นายอำเภอเรียก! ขอโทษที่ขัดจังหวะ แต่ฉันมาที่นี่เกี่ยวกับการต่อสู้ที่เกิดขึ้นเมื่อสองสามวันก่อน",
  str_homestory_N23dianying_90030301_67_dialog_content = "เจ้าของอยู่แถวนี้หรือเปล่า?",
  str_homestory_N23dianying_90030301_67X1_dialog_content = "เจ้าของอยู่แถวนี้หรือเปล่า?",
  str_homestory_N23dianying_90030301_68_dialog_content = "นายอำเภอ? ช่วงเวลาที่สมบูรณ์แบบ!",
  str_homestory_N23dianying_90030301_69_dialog_content = "ฉันเป็นบาร์เทนเดอร์ที่นี่ และฉันก็เป็นผู้เห็นเหตุการณ์ในการสนทนาทางอาญาเมื่อสักครู่นี้ พวกเขายังให้จดหมายที่เป็นความลับกับฉัน",
  str_homestory_N23dianying_90030301_70_dialog_content = "ฉันจะบอกคุณทุกอย่างที่ฉันรู้ ถ้าเพียงคุณเท่านั้นที่สามารถหยุดพวกอันธพาลไม่ให้ก้าวเข้ามาที่นี่อีก!",
  str_homestory_N23dianying_90030301_71_dialog_content = "จดหมายลับของแก๊งค์?",
  str_homestory_N23dianying_90030301_71X1_dialog_content = "จดหมายลับของแก๊งค์?",
  str_homestory_N23dianying_90030301_71X2_dialog_content = "ถูกตัอง. ถ้าคุณไปตามพวกเขาตอนนี้ คนที่ส่งจดหมายมาให้ผมคงอยู่ไม่ไกล",
  str_homestory_N23dianying_90030301_72_dialog_content = "คุณได้รับความช่วยเหลือมากมายจริงๆ ขอบคุณสำหรับความร่วมมือ บาร์เทนเดอร์",
  str_homestory_N23dianying_90030301_73_dialog_content = "เมื่อฉันรู้ว่าเกิดอะไรขึ้น ฉันจะรับผิดชอบดูแลสถานที่นี้ให้ปลอดภัย",
  str_homestory_N23dianying_90030301_74_dialog_content = "งั้นก็ลุยกันเลย!",
  str_homestory_N23dianying_90030301_74X1_dialog_content = "ฉันต้องดูว่ามันพูดอะไรก่อนถึงจะตัดสินความจริงของข้อมูลของคุณได้",
  str_homestory_N23dianying_90030301_74X2_dialog_content = "ฉันไม่เข้าใจว่าทำไมพวกเขาถึงมอบของสำคัญให้คุณ",
  str_homestory_N23dianying_90030301_74X3_dialog_content = "ดีเพียงแค่ได้รับกับมัน",
  str_homestory_N23dianying_90030301_75_dialog_content = "“สาวพระจันทร์สุดที่รักของฉัน”",
  str_homestory_N23dianying_90030301_76_dialog_content = "\"ฉันทั้งสองชื่นชมความกระตือรือร้นอย่างจริงใจของคุณและชื่นชมน้ำใสใจจริงที่กล้าหาญของคุณ\"",
  str_homestory_N23dianying_90030301_77_dialog_content = "“แต่ต้องขอโทษด้วยนะคะ ฉันรู้สึกไม่เหมือนเดิม”...",
  str_homestory_N23dianying_90030301_78_dialog_content = "มันคือจดหมายรัก ชับบ์!",
  str_homestory_N23dianying_90030301_79_dialog_content = "คุณทำอะไรอยู่?",
  str_homestory_N23dianying_90030301_80_dialog_content = "นี่คือ... จดหมายถึงฉันเหรอ?",
  str_homestory_N23dianying_90030301_81_dialog_content = "นี่มัน...",
  str_homestory_N23dianying_90030301_82_dialog_content = "นามปากกาของฉันคือ \"ความงามใต้แสงจันทร์\"...",
  str_homestory_N23dianying_90030301_83_dialog_content = "นี่ส่งถึงฉันใช่ไหม",
  str_homestory_N23dianying_90030301_84_dialog_content = "จ-ใช่.",
  str_homestory_N23dianying_90030301_85_dialog_content = "ฉันเพิ่งได้ยินชัด ๆ ว่าเขาไม่สามารถคืนความรู้สึกของฉันได้...",
  str_homestory_N23dianying_90030301_86_dialog_content = "ท้ายที่สุด ฉันยังทำไม่ได้เลย",
  str_homestory_N23dianying_90030301_87_dialog_content = "เฮ้! ทำไมคุณแตะเครื่องเล่นแผ่นเสียงของเรา!",
  str_homestory_N23dianying_90030301_87X1_dialog_content = "พรวดดด—",
  str_homestory_N23dianying_90030301_87X2_dialog_content = "ฮ่าฮ่าฮ่า",
  str_homestory_N23dianying_90030301_87X3_dialog_content = "ชารอน ใจเย็น! ชับบ์.",
  str_homestory_N23dianying_90030301_88_dialog_content = "ฉันพบเขาเมื่อเดือนที่แล้วภายใต้พระจันทร์เต็มดวง",
  str_homestory_N23dianying_90030301_89_dialog_content = "ตอนนั้นฉันซ่อนตัวจากพวกอันธพาล และเขาก็ช่วยฉันไว้",
  str_homestory_N23dianying_90030301_90_dialog_content = "เอ่อ... ทำไมเธอถึงบอกเราเรื่องนี้?",
  str_homestory_N23dianying_90030301_91_dialog_content = "ฉันถามไปทุกที่ในเมือง ก่อนที่ฉันจะรู้ว่าเขาเป็นใคร",
  str_homestory_N23dianying_90030301_92_dialog_content = "แต่ฉันหลงผิดถ้าคิดว่าผู้ชายที่รูปร่างสมส่วนจะตกหลุมรักคนอย่างฉันได้",
  str_homestory_N23dianying_90030301_93_dialog_content = "นั่นคือเหตุผลที่คุณเลือกใช้นามปากกาและเขียนจดหมายถึงเขาหรือไม่?",
  str_homestory_N23dianying_90030301_93X1_dialog_content = "นั่นคือเหตุผลที่คุณเลือกใช้นามปากกาและเขียนจดหมายถึงเขาหรือไม่?",
  str_homestory_N23dianying_90030301_94_dialog_content = "ใช่... เพราะฉันคิดว่า ไม่ว่าจะเกิดอะไรขึ้น ฉันจะไม่ยอมให้ตัวเองต้องเสียใจ",
  str_homestory_N23dianying_90030301_95_dialog_content = "แต่ฉันได้เรียนรู้ว่าช่องว่างบางช่องนั้นกว้างเกินกว่าจะฝ่าฟันด้วยความกล้าหาญเพียงลำพัง",
  str_homestory_N23dianying_90030301_95X1_dialog_content = "เป็นเรื่องที่น่าชื่นชมสำหรับผู้หญิงที่มีความกล้าหาญเช่นนี้",
  str_homestory_N23dianying_90030301_95X2_dialog_content = "เป็นการสูญเสียของเขาที่จะปฏิเสธผู้หญิงที่สง่างามเช่นนี้",
  str_homestory_N23dianying_90030301_96_dialog_content = "ฉันสามารถเข้าใจความรู้สึกของคุณอย่างแน่นอน Moon Maiden",
  str_homestory_N23dianying_90030301_97_dialog_content = "ความเห็นอกเห็นใจกำลังคืบคลานเข้ามา!",
  str_homestory_N23dianying_90030301_98_dialog_content = "ความจริงที่ว่าคุณมีความกล้าที่จะทำอย่างนั้นในตอนแรกนั้นน่าชื่นชม",
  str_homestory_N23dianying_90030301_99_dialog_content = "ฉันคิดว่าคุณไม่ควรยอมแพ้ในหัวใจของคุณอย่างรวดเร็ว ช่วยให้เขาเข้าใจคุณ",
  str_homestory_N23dianying_90030301_100_dialog_content = "อย่าโยนผ้าเช็ดตัวในอุปสรรคแรก",
  str_homestory_N23dianying_90030301_101_dialog_content = "ขอบคุณ... คุณเป็นคนแรกที่บอกฉันอย่างนั้น",
  str_homestory_N23dianying_90030301_101X1_dialog_content = "ฉันคือนายอำเภอแถวนี้ ดังนั้นถ้าคุณต้องการอะไรในอนาคต คุณต้องมาหาฉันแน่นอน",
  str_homestory_N23dianying_90030301_101X2_dialog_content = "และ... ฉันขอโทษที่อ่านจดหมายของคุณ ฉันไม่ควรทำอย่างนั้น",
  str_homestory_N23dianying_90030301_101X3_dialog_content = "ฉันเชื่อว่าคุณมีเจตนาดีเท่านั้น",
  str_homestory_N23dianying_90030301_101X4_dialog_content = "ขอขอบคุณสำหรับความเมตตาและความเข้าใจของคุณ",
  str_homestory_N23dianying_90030301_101X5_dialog_content = "สำหรับคุณ คุณชารอน",
  str_homestory_N23dianying_90030301_101X6_dialog_content = "เอ่อ... ครับ?",
  str_homestory_N23dianying_90030301_101X7_dialog_content = "ฉันควรเป็นมิสเตอร์บาร์เทนเดอร์ไม่ใช่เหรอ?",
  str_homestory_N23dianying_90030301_101X8_dialog_content = "ไม่มีทางที่ฉันจะให้อภัยคุณได้ ที่ยุ่งเรื่องส่วนตัวของหญิงสาว",
  str_homestory_N23dianying_90030301_101X9_dialog_content = "พฤติกรรมที่น่ารังเกียจเช่นนี้จะต้องถูกลงโทษตามกฎหมายและประณามด้วยศีลธรรมร่วมกัน!",
  str_homestory_N23dianying_90030301_101X10_dialog_content = "...!",
  str_homestory_N23dianying_90030301_101X11_dialog_content = "ลดเสียงลงพิตต์แมน!",
  str_homestory_N23dianying_90030301_101X12_dialog_content = "เขาดูเข้ากับตัวละครเกินไปหน่อย ชับบ์!",
  str_homestory_N23dianying_90030301_101X13_dialog_content = "เดี๋ยว เดี๋ยว เดี๋ยวก่อนสิ!",
  str_homestory_N23dianying_90030301_101X14_dialog_content = "เราไม่ได้ถ่ายทำเหรอ? สคริปต์พูดว่าอะไร?",
  str_homestory_N23dianying_90030301_101X15_dialog_content = "ไม่ใช่ว่าอยากอ่าน!",
  str_homestory_N23dianying_90030301_101X16_dialog_content = "ฮึ่ม ยังคงคร่ำครวญ",
  str_homestory_N23dianying_90030301_101X17_dialog_content = "รับโทษของคุณ!",
  str_homestory_N23dianying_90030301_101X18_dialog_content = "รอเดี๋ยวสิ",
  str_homestory_N23dianying_90030301_101X19_dialog_content = "อย่าไปทำลายชุดของฉันหรืออุปกรณ์ประกอบฉาก!",
  str_homestory_N23dianying_90030301_102_dialog_content = "ฉันคือนายอำเภอแถวนี้ ดังนั้นถ้าคุณต้องการอะไรในอนาคต คุณต้องมาหาฉันแน่นอน",
  str_homestory_N23dianying_90030301_103_dialog_content = "ยังไงก็ตาม ฉันยังมีสิ่งที่ต้องทำ ดังนั้นฉันควรจะออกไปได้แล้ว เจอกันรอบดึก.",
  str_homestory_N23dianying_90030301_104_dialog_content = "รอก่อน! แล้วการต่อสู้ล่ะ?",
  str_homestory_N23dianying_90030301_105_dialog_content = "จากสิ่งที่ฉันเพิ่งเห็น ฉันไม่พอใจที่คุณสามารถให้ข้อมูลที่เชื่อถือได้",
  str_homestory_N23dianying_90030301_106_dialog_content = "เป็นเรื่องที่น่ารังเกียจมากที่จะเข้าไปยุ่งเรื่องส่วนตัวของผู้หญิง",
  str_homestory_N23dianying_90030301_107_dialog_content = "ฉันจะประเมินและตัดสินตัวเอง ลาก่อน.",
  str_homestory_N23dianying_90030301_108_dialog_content = "เป็นไปได้ยังไงกัน...",
  str_homestory_N23dianying_90030301_109_dialog_content = "ชายผู้นั้นเมื่อกี้ เขาคือ... นายอำเภอจริงๆเหรอ?",
  str_homestory_N23dianying_90030301_110_option_content = "ขอโทษอย่างจริงใจ",
  str_homestory_N23dianying_90030301_110X1_dialog_content = "อย่าเพิ่งยืนตรงนั้น ผู้ดูแล! ขอโทษนะ!",
  str_homestory_N23dianying_90030301_111_dialog_content = "ได้สิ",
  str_homestory_N23dianying_90030301_112_dialog_content = "ฉันขอโทษที่เปิดจดหมายส่วนตัวที่สำคัญเช่นนี้โดยไม่ได้รับอนุญาต",
  str_homestory_N23dianying_90030301_113_dialog_content = "ไม่เป็นไร. ท้ายที่สุด มันคือการตัดสินใจในช่วงเวลาวิกฤติเพื่อประโยชน์ขององค์กร",
  str_homestory_N23dianying_90030301_114_dialog_content = "องค์กร?",
  str_homestory_N23dianying_90030301_115_dialog_content = "จดหมายถูกเขียนด้วยรหัส ดูเหมือนเป็นเพียงจดหมายรัก",
  str_homestory_N23dianying_90030301_116_dialog_content = "ในขณะที่มีความเสี่ยงโดยธรรมชาติในการเปิดมันต่อหน้านายอำเภอ... ดูเหมือนว่าเราจะหนีไปกับมันได้ เพราะเธอไม่ได้สงสัยเลยสักนิด",
  str_homestory_N23dianying_90030301_117_dialog_content = "และ Night Impression ก็มีชื่อเสียงในฐานะสถานประกอบการที่น่าเชื่อถือ",
  str_homestory_N23dianying_90030301_118_dialog_content = "เดี๋ยวนะ คุณหมายถึงคุณเป็นส่วนหนึ่งของแก๊งค์จริงๆเหรอ?",
  str_homestory_N23dianying_90030301_119_dialog_content = "ทั้งหมดนั้นถูกสร้างขึ้นมาตรงจุด?",
  str_homestory_N23dianying_90030301_120_dialog_content = "นั่นสิ",
  str_homestory_N23dianying_90030301_121_dialog_content = "ว้าว! ไม่เห็นจะเกิดขึ้นเลย ชับบ์!",
  str_homestory_N23dianying_90030301_122_dialog_content = "อย่างไรก็ตาม... ตอนนี้ฉันได้รับจดหมายอย่างปลอดภัยแล้ว ฉันควรจะไปที่จุดต่อไปในภารกิจนี้",
  str_homestory_N23dianying_90030301_123_dialog_content = "แล้วเจอกันครับ คุณบาร์เทนเดอร์",
  str_homestory_N23dianying_90030301_124_dialog_content = "...",
  str_homestory_N23dianying_90030301_125_dialog_content = "เกิดอะไรขึ้น?!",
  str_homestory_N23dianying_90030301_126_option_content = "แนะนำให้เธอยอมแพ้",
  str_homestory_N23dianying_90030301_126X1_dialog_content = "เอาละ ผู้ดูแล รออะไรอยู่ นี่เป็นส่วนที่คุณตั้งใจจะคุยกับเธอเกี่ยวกับการไล่ตามความสัมพันธ์!",
  str_homestory_N23dianying_90030301_127_dialog_content = "ได้สิ",
  str_homestory_N23dianying_90030301_128_dialog_content = "ถูกต้อง Moon Maiden... มีบางอย่างที่ฉันต้องบอกคุณ",
  str_homestory_N23dianying_90030301_129_dialog_content = "มันเกิดขึ้นเพียงว่าคนที่คุณชื่นชมเป็นบุคคลอันตรายในแก๊งค์!",
  str_homestory_N23dianying_90030301_130_dialog_content = "...!",
  str_homestory_N23dianying_90030301_131_dialog_content = "นายอำเภอเพิ่งไม่เชื่อฉัน นั่นคือเหตุผลที่เธอสนับสนุนให้คุณไล่ตาม",
  str_homestory_N23dianying_90030301_132_dialog_content = "แต่ฉันก็ยังแนะนำให้คุณเดินออกไป จะเป็นอย่างไรถ้าเขาไม่ใช่สุภาพบุรุษใจดีที่คุณคิดว่าเขาเป็นจริงๆ",
  str_homestory_N23dianying_90030301_133_dialog_content = "... คุณต้องการเปิดเผยตัวตนที่แท้จริงของเขาต่อนายอำเภอหรือไม่?",
  str_homestory_N23dianying_90030301_134_dialog_content = "ใช่. แม้ว่านายอำเภอจะไม่เชื่อฉัน ฉันก็จะไม่เลิกติดตามเบาะแส",
  str_homestory_N23dianying_90030301_135_dialog_content = "...",
  str_homestory_N23dianying_90030301_136_dialog_content = "สาวจันทร์?",
  str_homestory_N23dianying_90030301_137_dialog_content = "ค-จะทำอะไร!",
  str_homestory_N23dianying_90030301_138_dialog_content = "ตอนแรกฉันคิดว่านายอำเภอบังคับคุณให้อ่านจดหมาย",
  str_homestory_N23dianying_90030301_139_dialog_content = "สุภาพบุรุษผู้นั้นทำผิดพลาด...?",
  str_homestory_N23dianying_90030301_140_dialog_content = "ว-คุณหมายถึงอะไร?",
  str_homestory_N23dianying_90030301_141_dialog_content = "จดหมายถูกเขียนด้วยรหัส ดูเหมือนเป็นเพียงจดหมายรัก",
  str_homestory_N23dianying_90030301_142_dialog_content = "เพื่อป้องกันไม่ให้เกิดวิกฤตเช่นนี้",
  str_homestory_N23dianying_90030301_143_dialog_content = "และฉันก็เป็นหนึ่งในผู้เล่นในภารกิจลับนี้",
  str_homestory_N23dianying_90030301_144_dialog_content = "ว้าว! ไม่เห็นจะเกิดขึ้นเลย ชับบ์!",
  str_homestory_N23dianying_90030301_145_dialog_content = "รอก่อน! คุณเป็นส่วนหนึ่งของแก๊งค์จริงๆเหรอ!",
  str_homestory_N23dianying_90030301_146_dialog_content = "ใช่... ฉันขอโทษสำหรับอุบาย",
  str_homestory_N23dianying_90030301_147_dialog_content = "แต่ความปลอดภัยขององค์กรเป็นสิ่งสำคัญยิ่ง ได้โปรด คุณบาร์เทนเดอร์...",
  str_homestory_N23dianying_90030301_148_dialog_content = "เธอจะต้องหุบปาก...ตลอดไป",
  str_homestory_N23dianying_90030301_149_dialog_content = "ว-คุณกำลังทำอะไร?",
  str_homestory_N23dianying_90030301_150_dialog_content = "ถอยไป!",
  str_homestory_N23dianying_90030301_151_option_content = "ตัวตนของคำถาม",
  str_homestory_N23dianying_90030301_151X1_dialog_content = "ปุยเส้นของคุณ? คุณกำลังตั้งคำถามถึงตัวตนของเธอ ผู้ดูแล!",
  str_homestory_N23dianying_90030301_152_dialog_content = "ฟังดูถูกต้อง",
  str_homestory_N23dianying_90030301_153_dialog_content = "แล้วสาวจันทร์?",
  str_homestory_N23dianying_90030301_154_dialog_content = "อะไรเหรอ?",
  str_homestory_N23dianying_90030301_155_dialog_content = "คุณเป็นแค่แฟนตัวยงที่ถูกปฏิเสธจริงๆหรือ?",
  str_homestory_N23dianying_90030301_156_dialog_content = "...",
  str_homestory_N23dianying_90030301_157_dialog_content = "รู้มากไปก็ไม่ดีนะ คุณบาร์เทนเดอร์",
  str_homestory_N23dianying_90030301_158_dialog_content = "แต่ฉันจะไปตามทางของฉัน เมื่อมีจดหมายแล้ว",
  str_homestory_N23dianying_90030301_159_dialog_content = "ฉันรู้ว่าบางอย่างมีกลิ่นคาว",
  str_homestory_N23dianying_90030301_160_dialog_content = "ฉันแน่ใจว่าจดหมายฉบับนั้นมีอะไรมากกว่าที่คิด ฉันควรจดบันทึกสิ่งที่พูดไว้ในขณะที่ฉันยังจำได้",
  str_homestory_N23dianying_90030301_161_dialog_content = "ปากกากับกระดาษอยู่ไหน...",
  str_homestory_N23dianying_90030301_162_dialog_content = "คุณไม่สามารถทิ้งมันไว้คนเดียวได้ไหม?",
  str_homestory_N23dianying_90030301_163_dialog_content = "จ-คุณยัง—",
  str_homestory_N23dianying_90030301_164_dialog_content = "ชู! ข้อตำหนิ! ชับบ์!",
  str_homestory_N23dianying_90030301_165_dialog_content = "พระเอกหนังไม่เช็คห้อง ชับบ์!",
  str_homestory_N23dianying_90030301_166_dialog_content = "ทำไมสุภาพบุรุษคนนั้นถึงมอบของสำคัญให้คุณ?",
  str_homestory_N23dianying_90030301_167_dialog_content = "เว้นแต่จะเป็นส่วนหนึ่งของแผนทั้งหมด?",
  str_homestory_N23dianying_90030301_168_dialog_content = "โดยไม่คำนึงถึงเพื่อป้องกันสิ่งรบกวนที่ไม่คาดคิดเกิดขึ้น ทำไมไม่ไปเดินเล่นด้วยกันสักหน่อย คุณบาร์เทนเดอร์?",
  str_homestory_N23dianying_90030301_169_dialog_content = "รอ! คุณกำลังทำอะไรอยู่?!",
  str_homestory_N23dianying_90030301_170_dialog_content = "ถอยไป!",
  str_homestory_N23dianying_90030301_171_dialog_content = "อย่าเป็นอะไรมากนะ เจ้าพวกพึมพำ...",
  str_homestory_N23dianying_90030301_172_dialog_content = "ใจเย็นๆ คุณบาร์เทนเดอร์ เราไม่ได้ตั้งใจจะรบกวนคุณ",
  str_homestory_N23dianying_90030301_172X1_dialog_content = "ฉันเป็นเพื่อนที่ดีกับเจ้านายของคุณ เขาจะไม่พูดอะไรถ้าฉันใช้พื้นที่เล็กน้อยที่นี่",
  str_homestory_N23dianying_90030301_173_dialog_content = "เรายังเป็นเพื่อนที่ดีกับเจ้านาย ฉันแน่ใจว่าเขาจะไม่เป็นไร",
  str_homestory_N23dianying_90030301_174_dialog_content = "เอ่อ... บอส?",
  str_homestory_N23dianying_90030301_175_dialog_content = "... ดี. ฉันเข้าใจแล้ว.",
  str_homestory_N23dianying_90030301_176_dialog_content = "แดรท. ใช้เจ้านายตัวเองข่มขู่ฉัน",
  str_homestory_N23dianying_90030301_177_dialog_content = "สถานที่แห่งนี้จะไม่มีอะไรนอกจากการแฮงค์เอาท์ของแก๊งค์ในอัตรานี้",
  str_homestory_N23dianying_90030301_178_dialog_content = "ฉันขอโทษ นี่ไม่ใช่สิ่งที่เราตกลงกัน ไม่มีทางที่ฉันจะยอมรับได้",
  str_homestory_N23dianying_90030301_179_dialog_content = "หลังจากหลายปีแห่งมิตรภาพนี้ คุณช่วยขยับตัวหน่อยไม่ได้เหรอ?",
  str_homestory_N23dianying_90030301_179X1_dialog_content = "คุณเป็นเหมือนพี่น้องกับฉันมาหลายปีแล้ว หาห้องกระดิกหน่อยไม่ได้เหรอ?",
  str_homestory_N23dianying_90030301_180_dialog_content = "มันเป็นแค่ธุรกิจ ทั้งหมดยุติธรรมในความรักและห้างสรรพสินค้า มันคือสนามรบ ไม่ใช่ที่สำหรับหาเพื่อน",
  str_homestory_N23dianying_90030301_181_dialog_content = "ถ้าคุณอยู่ในรองเท้าของฉัน คุณจะทำแบบเดียวกัน",
  str_homestory_N23dianying_90030301_182_dialog_content = "และคุณไม่ได้คิดว่าฉันเป็นเพื่อนแท้ ตัดสินโดยวิธีที่คุณแก้ไขสัญญาครั้งล่าสุด",
  str_homestory_N23dianying_90030301_183_dialog_content = "อา นั่นเป็นเพียงความเข้าใจผิดเล็กน้อย",
  str_homestory_N23dianying_90030301_184_dialog_content = "โอ้? ครั้งสุดท้ายที่คุณเข้าไปยุ่งเกี่ยวกับธุรกิจของเราก็เป็นความเข้าใจผิดด้วยหรือเปล่า?",
  str_homestory_N23dianying_90030301_185_dialog_content = "เกี่ยวกับสิ่งนั้น...",
  str_homestory_N23dianying_90030301_186_dialog_content = "หรือครั้งก่อนหน้านั้นเมื่อคุณวิ่งไปดมกลิ่นนายอำเภอ?",
  str_homestory_N23dianying_90030301_187_dialog_content = "หนุ่มๆ ไม่กี่คนที่จากเราไปได้พยายามอย่างเต็มที่เพื่อปกป้องสินค้าของเจ้านาย แต่เราจ่ายในราคาที่สูงมาก",
  str_homestory_N23dianying_90030301_188_dialog_content = "...",
  str_homestory_N23dianying_90030301_189_dialog_content = "ฉันไม่เข้าใจจริงๆ ว่าทำไมคนพวกนั้นถึงยังเต็มใจที่จะร่วมงานกับคุณ",
  str_homestory_N23dianying_90030301_190_dialog_content = "แต่ฉัน... ฉันรอที่จะแสดงให้คุณเห็นว่าคุณโกรธฉันแค่ไหน",
  str_homestory_N23dianying_90030301_191_dialog_content = "และคุณกล้าใช้คำว่า 'เพื่อน' กับฉันไหม!",
  str_homestory_N23dianying_90030301_192_dialog_content = "เอาล่ะ ตอนนี้—ถ้าคุณจะสู้ ให้ไปที่อื่น",
  str_homestory_N23dianying_90030301_193_dialog_content = "นั่นคือวิธีการเจรจาทำงาน!",
  str_homestory_N23dianying_90030301_194_dialog_content = "เลิกกับการเสแสร้ง ทุกคนออกไปเพื่อตัวเอง ไม่มีถูกหรือผิดที่นี่",
  str_homestory_N23dianying_90030301_195_dialog_content = "ที่ผ่านมาคุณเคยแอบส่งข้อมูลเกี่ยวกับเราไปยัง Lionhead Gang หรือเปล่า?",
  str_homestory_N23dianying_90030301_196_dialog_content = "เราแค่คืนความโปรดปราน การปรับสมดุลตาชั่ง",
  str_homestory_N23dianying_90030301_197_dialog_content = "ดูเหมือนคุณจะโกรธเรามาก",
  str_homestory_N23dianying_90030301_198_dialog_content = "ดังนั้นมาตัดสินคะแนนทั้งหมดในวันนี้ ที่นี่ และตอนนี้",
  str_homestory_N23dianying_90030301_199_dialog_content = "ไม่เป็นไร ถ้าเธอกล้ายอมรับความผิดพลาดของตัวเอง",
  str_homestory_N23dianying_90030301_200_dialog_content = "อย่าทะเลาะกันที่นี่ คุณสองคน!",
  str_homestory_N23dianying_90030301_201_dialog_content = "ทุกคนหยุด! วางอาวุธลง!",
  str_homestory_N23dianying_90030301_202_dialog_content = "ฉันเพิ่งจัดสถานที่เสร็จ!",
  str_homestory_N23dianying_90030301_202X1_dialog_content = "ฉันพูดเสมอว่าเป็นความเข้าใจผิด",
  str_homestory_N23dianying_90030301_202X2_dialog_content = "เราไม่สามารถเขียนแบบแข็งเหมือนที่คุณเขียนได้",
  str_homestory_N23dianying_90030301_202X3_dialog_content = "โอ้? คราวที่แล้วที่คุณไปขโมยสินค้าของเรา นั่นเป็นความเข้าใจผิดด้วยเหรอ?",
  str_homestory_N23dianying_90030301_202X4_dialog_content = "อืม...",
  str_homestory_N23dianying_90030301_202X5_dialog_content = "Shadowlord ให้ข้าไล่ตามเจ้าข้ามทะเลทราย Rediesel เป็นเวลาสามวันเต็มคืน",
  str_homestory_N23dianying_90030301_202X6_dialog_content = "คุณแค่เดินไปรอบๆ และทำสิ่งต่างๆ ให้ยุ่งเหยิงก่อนที่จะโยนมันกลับมาให้ฉัน",
  str_homestory_N23dianying_90030301_202X7_dialog_content = "นั่นก็เป็นความเข้าใจผิดเหมือนกันใช่ไหม?",
  str_homestory_N23dianying_90030301_202X8_dialog_content = "เฮ้ เราไม่ทำหนังเหรอ?",
  str_homestory_N23dianying_90030301_202X9_dialog_content = "คุณกำลังเลือกที่จะนำเสนอทั้งหมดนี้หรือไม่?",
  str_homestory_N23dianying_90030301_202X10_dialog_content = "ทากิ ซินซา ได้โปรดใจเย็นๆ!",
  str_homestory_N23dianying_90030301_202A1_dialog_content = "พวกเขาเริ่มต่อสู้กันแล้ว!",
  str_homestory_N23dianying_90030301_202X11_dialog_content = "ฉันขอโทษ แต่ฉันไม่คิดว่าเราจะถ่ายทำต่อได้",
  str_homestory_N23dianying_90030301_202X12_dialog_content = "ฉันแทบกลั้นอารมณ์โกรธไม่ได้ตั้งแต่เห็นหน้าคุณในกองถ่ายครั้งแรก",
  str_homestory_N23dianying_90030301_202X13_dialog_content = "น่าหลงใหล. แล้วคุณจะทำอย่างไรกับมัน? อยากแทงโก้?",
  str_homestory_N23dianying_90030301_202X14_dialog_content = "เอาเลย",
  str_homestory_N23dianying_90030301_202X15_dialog_content = "ออกไปถ้าจะสู้! อย่าทำลายชุดหรืออุปกรณ์ประกอบฉาก!",
  str_homestory_N23dianying_90030401_1_dialog_content = "ไม่สบายหรือเปล่า ฝ่าบาท?",
  str_homestory_N23dianying_90030401_2_dialog_content = "โนวิโอบอกว่าช่วงนี้คุณทานอาหารไม่ดี",
  str_homestory_N23dianying_90030401_3_dialog_content = "พวกเขาเป็นห่วงและพยายามหาสูตรอาหารใหม่ๆ ให้คุณ",
  str_homestory_N23dianying_90030401_4_dialog_content = "ขอโทษที่ทำให้ทุกคนเป็นห่วงนะ โลล่า",
  str_homestory_N23dianying_90030401_5_dialog_content = "ช่วงนี้ฉันไม่ค่อยอยากอาหารเท่าไหร่ ไม่จำเป็นต้องกังวล",
  str_homestory_N23dianying_90030401_6_dialog_content = "ทำไมไม่ลองน้ำผึ้งที่เพิ่งเก็บมาล่ะ? มันหวานจริงๆ!",
  str_homestory_N23dianying_90030401_S6_dialog_content = "หรือถ้าคุณไม่อยากกินน้ำผึ้ง เราก็มีเมนูใหม่ๆ",
  str_homestory_N23dianying_90030401_7_dialog_content = "น้ำผึ้งนั้นดี แต่น้ำตาลไม่ดีต่อร่างกายจริงๆ",
  str_homestory_N23dianying_90030401_8_dialog_content = "หืม? ใครน่ะ?",
  str_homestory_N23dianying_90030401_X8_dialog_content = "สาวน้อย ของหวานมากเกินไปจะทำให้คุณอ้วน",
  str_homestory_N23dianying_90030401_S8_dialog_content = "ฝ่าบาท",
  str_homestory_N23dianying_90030401_S9_dialog_content = "ฉันชื่อเชฟอีฟ จ้างโดยคุณโนวิโอเพื่อทำอาหารใหม่ๆ ให้คุณ",
  str_homestory_N23dianying_90030401_9_dialog_content = "ขอแสดงความเสียใจ ฝ่าบาท",
  str_homestory_N23dianying_90030401_10_dialog_content = "ฉันชื่อเชฟเฟลอร์ จ้างโดยคุณโนวิโอ ทำอาหารใหม่ๆ ให้คุณ",
  str_homestory_N23dianying_90030401_11_dialog_content = "ฉันมาจากทะเลทรายเรดีเซล ไกลจากแดนเหนือ",
  str_homestory_N23dianying_90030401_12_dialog_content = "ฉันเชื่อว่าฉันจะสามารถนำเสนออาหารที่คุณไม่เคยลิ้มลองมาก่อน",
  str_homestory_N23dianying_90030401_13_dialog_content = "เห็น Rediesel Brew นี้ไหม ซึ่งแตกต่างจากเครื่องดื่มที่คุณมีที่นี่",
  str_homestory_N23dianying_90030401_14_dialog_content = "ฉันแน่ใจว่ารสชาติกลมกล่อมอันเป็นเอกลักษณ์จะกระตุ้นต่อมรับรสของคุณ",
  str_homestory_N23dianying_90030401_X14_dialog_content = "ฉันเป็นเชฟคนใหม่ที่จ้างโดยโนวิโอที่น่ารักคนนั้น",
  str_homestory_N23dianying_90030401_X15_dialog_content = "ฉันมาจากทะเลทรายเรดีเซล และนำอาหารที่คุณไม่เคยได้ยินชื่อมาด้วย",
  str_homestory_N23dianying_90030401_X16_dialog_content = "นี่คือพระราชวังฤดูหนาว เรามีอาหารทุกจานจากทุกมุมของทวีป!",
  str_homestory_N23dianying_90030401_X17_dialog_content = "สงสัยจะเป็นเช่นนั้นสาวน้อย",
  str_homestory_N23dianying_90030401_X18_dialog_content = "เห็น Rediesel Brew นี้ไหม ซึ่งแตกต่างจากเครื่องดื่มที่คุณมีที่นี่",
  str_homestory_N23dianying_90030401_X19_dialog_content = "เป็นสูตรเฉพาะของ Rediesel Desert และสืบทอดมาและไม่พบในบันทึกใดๆ",
  str_homestory_N23dianying_90030401_S14_dialog_content = "ไม่เพียงเท่านั้น แต่ยังกระตุ้นได้มากกว่าเครื่องดื่มอื่นๆ อีกด้วย",
  str_homestory_N23dianying_90030401_S15_dialog_content = "ครั้งสุดท้าย, PlayerName ได้ดื่มกับพี่ชายของฉันเพียงไม่กี่อึดใจและ...",
  str_homestory_N23dianying_90030401_S16_dialog_content = "ว-เดี๋ยวก่อน! นั่นไม่อยู่ในสคริปต์ อีฟ!",
  str_homestory_N23dianying_90030401_S17_dialog_content = "โอ้ใช่! แล้วสายของฉันคืออะไร?",
  str_homestory_N23dianying_90030401_S18_dialog_content = "โอ้ และมังกรสี่ขาทองคำตัวนี้",
  str_homestory_N23dianying_90030401_15_dialog_content = "มีกลิ่นหอมเฉพาะตัวแน่นอน",
  str_homestory_N23dianying_90030401_16_dialog_content = "คุณถูก! ฉันได้กลิ่นจากที่นี่แล้ว!",
  str_homestory_N23dianying_90030401_X20_dialog_content = "มังกรสี่ขาสีทองตัวนี้",
  str_homestory_N23dianying_90030401_17_dialog_content = "และมังกรสี่ขาสีทองตัวนี้",
  str_homestory_N23dianying_90030401_18_dialog_content = "มันทำมาจากกิ้งก่าทะเลทรายจากส่วนที่ลึกที่สุดของทะเลทราย เนื้อจะแน่นด้วยหนังกรอบ",
  str_homestory_N23dianying_90030401_19_dialog_content = "เป็นหนึ่งในอาหารที่มีชื่อเสียงที่สุดจากทะเลทรายเรดีเซล",
  str_homestory_N23dianying_90030401_20_dialog_content = "ฟังดูเข้าท่า.",
  str_homestory_N23dianying_90030401_21_dialog_content = "อืม... ต-นั่นต่างหาก",
  str_homestory_N23dianying_90030401_22_dialog_content = "สำหรับ Desert Jewel มันคือจานซิกเนเจอร์ของจริง",
  str_homestory_N23dianying_90030401_23_dialog_content = "มันทำมาจากอวัยวะภายในของไส้เดือนทราย ซึ่งเป็นสิ่งมีชีวิตที่มีเอกลักษณ์เฉพาะในทะเลทรายเรดีเซล",
  str_homestory_N23dianying_90030401_24_dialog_content = "I-อวัยวะภายในของหนอนทราย!?",
  str_homestory_N23dianying_90030401_25_dialog_content = "ถูกตัอง. ปรุงรสด้วยน้ำมันดีเซล และเครื่องปรุงรสเฉพาะของเรา จากนั้นนำไปคั่วจนผิวหนังไหม้เกรียมเล็กน้อย",
  str_homestory_N23dianying_90030401_26_dialog_content = "มันหอม ฉ่ำ และมีคุณค่าทางโภชนาการสูง—",
  str_homestory_N23dianying_90030401_27_dialog_content = "หยุด หยุด หยุด! เพียงพอ!",
  str_homestory_N23dianying_90030401_28_dialog_content = "ชาวประแจแลกดีเซลกินของแปลกจริงๆ!",
  str_homestory_N23dianying_90030401_29_dialog_content = "ท้องจะรับไหวได้ยังไง?",
  str_homestory_N23dianying_90030401_30_dialog_content = "เงียบ, โลล่า. เรากำลังอ่านโฆษณาที่นี่!",
  str_homestory_N23dianying_90030401_31_dialog_content = "ข-ขอโทษ...",
  str_homestory_N23dianying_90030401_32_dialog_content = "แน่นอนว่าฟังดูน่าสนใจ คุณต้องแสดงให้เราเห็นจาน",
  str_homestory_N23dianying_90030401_X32_dialog_content = "แน่นอนว่าฟังดูน่าสนใจ คุณต้องแสดงให้เราเห็นจาน",
  str_homestory_N23dianying_90030401_33_dialog_content = "ด้วยความยินดีค่ะ ฝ่าบาท",
  str_homestory_N23dianying_90030401_X33_dialog_content = "Rediesel Gourmet รสชาติที่แม้แต่ราชินีแห่งภาคเหนือก็หลงใหล",
  str_homestory_N23dianying_90030401_X34_dialog_content = "Rediesel Foodfest พร้อมให้บริการแล้วใน Rediesel Desert! ปีละ 4 ครั้งเท่านั้น!",
  str_homestory_N23dianying_90030401_X35_dialog_content = "คุณอาจจะเจอฉันที่นั่นถ้าคุณโชคดี",
  str_homestory_N23dianying_90030401_S33_dialog_content = "แน่นอนว่าฟังดูน่าสนใจ คุณต้องแสดงให้เราเห็นจาน",
  str_homestory_N23dianying_90030401_S34_dialog_content = "ด้วยความยินดี ฝ่าบาท!",
  str_homestory_N23dianying_90030401_34_dialog_content = "Rediesel Gourmet รสชาติที่แม้แต่ให้กำลังใจราชินีแห่งภาคเหนือ",
  str_homestory_N23dianying_90030401_35_dialog_content = "Rediesel Foodfest พร้อมให้บริการแล้วใน Rediesel Desert! ปีละ 4 ครั้งเท่านั้น!",
  str_homestory_N23dianying_90030401_36_dialog_content = "สนใจ? ติดต่อ Odd Jobs ผู้ทำงานร่วมกันของเราใน Umbraton!",
  str_homestory_N23dianying_90030401_37_dialog_content = "ส่วนลดกลุ่มสุดคุ้มและข้อเสนอดีๆ อื่นๆ สำหรับผู้สอบถาม 100 คนแรก!",
  str_homestory_N23dianying_90030401_38_dialog_content = "อย่าพลาด!",
  str_homestory_N23dianying_90030501_1_dialog_content = "คุณสบายดีไหม Miss Vice?",
  str_homestory_N23dianying_90030501_2_dialog_content = "โอ้ฉันขอโทษ. ฉันว่างเปล่าสักครู่ที่นั่น",
  str_homestory_N23dianying_90030501_3_dialog_content = "คุณกำลังพูดอะไร",
  str_homestory_N23dianying_90030501_X1_dialog_content = "ผู้อำนวยการ? คุณสบายดีไหม?",
  str_homestory_N23dianying_90030501_X2_dialog_content = "เสียใจ! ฉันว่างเปล่าสักครู่ที่นั่น",
  str_homestory_N23dianying_90030501_X3_dialog_content = "พูดอะไรน่ะ",
  str_homestory_N23dianying_90030501_S1_dialog_content = "นายไมนอส? คุณสบายดีไหม?",
  str_homestory_N23dianying_90030501_S2_dialog_content = "โอ้ฉันขอโทษ.",
  str_homestory_N23dianying_90030501_S3_dialog_content = "คุณถามคำถามซ้ำอีกครั้งได้ไหม",
  str_homestory_N23dianying_90030501_S4_dialog_content = "ไม่เป็นไร. คุณดูเหนื่อย...",
  str_homestory_N23dianying_90030501_S5_dialog_content = "สิ่งที่ฉันอยากจะถามคือ... ครั้งที่แล้ว คุณบอกว่าคุณเสียใจที่ทำหนังเรื่องนี้",
  str_homestory_N23dianying_90030501_4_dialog_content = "แน่นอน. ที่อยากถามคือ...",
  str_homestory_N23dianying_90030501_5_dialog_content = "คราวที่แล้วคุณบอกว่าคุณเสียใจที่ทำหนังเรื่องนี้",
  str_homestory_N23dianying_90030501_6_dialog_content = "ทำไมกันนะ",
  str_homestory_N23dianying_90030501_X4_dialog_content = "ม-เป็นเพราะเรารู้จนกระทั่งมันถูกปล่อยออกมาว่า...",
  str_homestory_N23dianying_90030501_X5_dialog_content = "ภาพยนตร์เรื่องนี้อาจสาปแช่ง",
  str_homestory_N23dianying_90030501_S6_dialog_content = "แม้ว่าฉันจะไม่สนับสนุนไสยศาสตร์แบบนี้ แต่โดยส่วนตัว...",
  str_homestory_N23dianying_90030501_S7_dialog_content = "แต่พวกเขาทั้งหมดบอกว่าภาพยนตร์เรื่องนี้สาปแช่ง",
  str_homestory_N23dianying_90030501_7_dialog_content = "เพราะ...ยังไม่ถูกปล่อยออกมา เราจึงได้รู้ว่า...",
  str_homestory_N23dianying_90030501_8_dialog_content = "ภาพยนตร์เรื่องนี้อาจสาปแช่ง",
  str_homestory_N23dianying_90030501_9_dialog_content = "สาป?",
  str_homestory_N23dianying_90030501_10_dialog_content = "ใช่. ทุกท่านที่ได้ชมภาพยนตร์หรือมีส่วนร่วมในการจัดทำ...",
  str_homestory_N23dianying_90030501_11_dialog_content = "ล้วนมีประสบการณ์ \"แปลก\"",
  str_homestory_N23dianying_90030501_12_dialog_content = "สวัสดีทุกๆคน. วันนี้ฉันมาที่นี่เพื่อพาคุณเข้าไปในบ้านผีสิง Andersen!",
  str_homestory_N23dianying_90030501_13_dialog_content = "เดิมเป็นของ Lady Astor",
  str_homestory_N23dianying_90030501_14_dialog_content = "เธอจะกรีดร้องเมื่อเทียนดับ",
  str_homestory_N23dianying_90030501_15_dialog_content = "ในที่สุดเธอก็เสียชีวิตในกองไฟ",
  str_homestory_N23dianying_90030501_16_dialog_content = "สไตล์เจ้าของเดิม...มีเอกลักษณ์เฉพาะตัวจริงๆ",
  str_homestory_N23dianying_90030501_17_dialog_content = "มันเป็นแค่หุ่นเชิดเหล่านี้ พวกมันดูแปลกประหลาด",
  str_homestory_N23dianying_90030501_18_dialog_content = "<color=#e8d9bb>*กล่องดนตรีไขมีเสียง*</color>",
  str_homestory_N23dianying_90030501_19_dialog_content = "\"ตัวเล็กหนึ่งตัว สองตัวเล็กๆ สามตัว♪\"",
  str_homestory_N23dianying_90030501_20_dialog_content = "อะ-อะแฮ่ม!!!! มันกลับมาแล้ว!",
  str_homestory_N23dianying_90030501_X20_dialog_content = "ฉันได้ยินผู้หญิงคนนั้นร้องเพลงนี้ทุกคืนตั้งแต่วันนั้น!",
  str_homestory_N23dianying_90030501_X21_dialog_content = "และฉันสังเกตเห็นว่าเสียงของเธอดูเหมือนจะเข้ามาใกล้ฉันมากขึ้นเรื่อยๆ!",
  str_homestory_N23dianying_90030501_X22_dialog_content = "เพื่อนนักแสดงของฉันก็บอกฉันในสิ่งเดียวกัน",
  str_homestory_N23dianying_90030501_S20_dialog_content = "นักแสดงและทีมงานบางคนได้ยินเธอร้องเพลงทุกคืนตั้งแต่นั้นเป็นต้นมา",
  str_homestory_N23dianying_90030501_S21_dialog_content = "แต่โดยส่วนตัวไม่ได้ยินอะไรเลย",
  str_homestory_N23dianying_90030501_S22_dialog_content = "เป็นไปได้ไหมว่าพวกเขาเหนื่อยเกินไปหรือเห็นภาพหลอน?",
  str_homestory_N23dianying_90030501_21_dialog_content = "ฉันได้ยินผู้หญิงคนนั้นร้องเพลงนี้ทุกคืนตั้งแต่วันนั้น!",
  str_homestory_N23dianying_90030501_22_dialog_content = "และฉันสังเกตเห็นว่าเสียงของเธอดูเหมือนจะเข้ามาใกล้ฉันมากขึ้นเรื่อยๆ!",
  str_homestory_N23dianying_90030501_23_dialog_content = "เป็นไปได้ไหมว่าคุณเหนื่อยเกินไปหรือมีอาการประสาทหลอน?",
  str_homestory_N23dianying_90030501_24_dialog_content = "ฉันยังดูหนังเรื่องนี้ก่อนการสัมภาษณ์ครั้งนี้",
  str_homestory_N23dianying_90030501_25_dialog_content = "ไม่มีอะไรเกิดขึ้นกับฉัน",
  str_homestory_N23dianying_90030501_26_dialog_content = "อาจเป็นแค่เรื่องบังเอิญ...?",
  str_homestory_N23dianying_90030501_27_dialog_content = "<color=#e8d9bb>*ฝีเท้าใกล้เข้ามา*</color>",
  str_homestory_N23dianying_90030501_X27_dialog_content = "เสียงอะไรน่ะ?",
  str_homestory_N23dianying_90030501_S27_dialog_content = "ว-นั่นเสียงอะไรน่ะ?",
  str_homestory_N23dianying_90030501_S28_dialog_content = "ลมคงพัดอะไรมากระทบกระเทือน...",
  str_homestory_N23dianying_90030501_28_dialog_content = "ว-นั่นอะไรน่ะ...?",
  str_homestory_N23dianying_90030501_29_dialog_content = "ฉันไม่รู้ ดูเหมือนว่ามีบางอย่างถูกเคาะเหนือ",
  str_homestory_N23dianying_90030501_30_dialog_content = "\"ตัวเล็กหนึ่งตัว สองตัวเล็กๆ สามตัว♪\"",
  str_homestory_N23dianying_90030501_S30_dialog_content = "อะ-อะแฮ่ม!!!! ท- นั่นคือเพลง!",
  str_homestory_N23dianying_90030501_S31_dialog_content = "นี่มัน...",
  str_homestory_N23dianying_90030501_31_dialog_content = "อื้อหือ! นั่นคือเพลง!",
  str_homestory_N23dianying_90030501_X31_dialog_content = "ว้าว! แค่นั้นแหละ! นั่นคือเพลง!",
  str_homestory_N23dianying_90030501_32_dialog_content = "\"สี่ตัวเล็ก ห้าตัว หกหุ่น♪\"",
  str_homestory_N23dianying_90030501_S32_dialog_content = "ก-เกิดอะไรขึ้นน่ะ?",
  str_homestory_N23dianying_90030501_S33_dialog_content = "อย่าตื่นตระหนก อยู่ในความสงบ",
  str_homestory_N23dianying_90030501_33_dialog_content = "ก-เกิดอะไรขึ้นน่ะ?",
  str_homestory_N23dianying_90030501_34_dialog_content = "<color=#e8d9bb>เพล้ง!</color>",
  str_homestory_N23dianying_90030501_35_dialog_content = "T-ไฟเพิ่งดับ!",
  str_homestory_N23dianying_90030501_36_dialog_content = "\"เจ็ดน้อย, แปดน้อย, เก้าหุ่นเชิด♪\"",
  str_homestory_N23dianying_90030501_X36_dialog_content = "ไม่นะ. ฉันผิดเองที่ทำหนังเรื่องนี้...",
  str_homestory_N23dianying_90030501_S36_dialog_content = "คุณ สวิตช์หลักสำหรับไฟอยู่ที่ไหน บอกฉันตอนนี้!",
  str_homestory_N23dianying_90030501_37_dialog_content = "ทั้งหมดเป็นเพราะหนังเรื่องนี้...มันต้องโดนสาปแน่ๆ...",
  str_homestory_N23dianying_90030501_38_dialog_content = "\"ตุ๊กตาเก้าตัว มีเพียงแปดหัวเท่านั้น♪\"",
  str_homestory_N23dianying_90030501_39_dialog_content = "หึหึ... เจ้ากล้าดูไหม?",
  str_homestory_N23dianying_90030601_1_dialog_content = "น.ส.สีบาน การเตรียมการสำหรับปฏิบัติการพิเศษเสร็จเรียบร้อยแล้ว เราสามารถดำเนินการได้ตลอดเวลา",
  str_homestory_N23dianying_90030601_2_dialog_content = "ขอขอบคุณ! ตอนนี้เรากำลังรอให้จอมพลซ้อมโฆษณาการเกณฑ์ทหารในร่มร่วมกัน...",
  str_homestory_N23dianying_90030601_X1_dialog_content = "ผู้บัญชาการวิเวียน การเตรียมการสำหรับปฏิบัติการพิเศษเสร็จเรียบร้อยแล้ว เราสามารถดำเนินการได้ตลอดเวลา",
  str_homestory_N23dianying_90030601_X2_dialog_content = "งานดี. ท่านจอมพลควรอยู่ที่นี่ทุกเวลา เราจะเริ่มการซ้อมโฆษณาการเกณฑ์ทหารในร่มทันทีหลังจากนั้น",
  str_homestory_N23dianying_90030601_S1_dialog_content = "ผู้บัญชาการบาร์ตัน การเตรียมการสำหรับปฏิบัติการพิเศษเสร็จเรียบร้อยแล้ว เราสามารถดำเนินการได้ตลอดเวลา",
  str_homestory_N23dianying_90030601_S2_dialog_content = "งานดี. จอมพลจะอยู่ที่นี่ทุกเวลา เราจะเริ่มการซ้อมโฆษณาการเกณฑ์ทหารในร่มทันทีหลังจากนั้น",
  str_homestory_N23dianying_90030601_3_dialog_content = "ขอโทษที่ให้รอนะคะทุกคน",
  str_homestory_N23dianying_90030601_4_dialog_content = "นี่เป็นความพยายามครั้งแรกของฉันในการสรรหาบุคลากรที่มีนวัตกรรมดังกล่าว โปรดรักษาจิตวิญญาณของคุณไว้ แล้วเราจะแสดงให้โลกเห็นว่าทหารของ Illumina นั้นกล้าหาญเพียงใด!",
  str_homestory_N23dianying_90030601_5_dialog_content = "ครับ!",
  str_homestory_N23dianying_90030601_6_dialog_content = "ฉันหวังว่าวันนี้จะเป็นวันเกิดของคุณ",
  str_homestory_N23dianying_90030601_7_dialog_content = "คุณผ่านพ้นไปแล้ว สิ่งสำคัญคือคุณจะเป็นใครในวันนี้และพรุ่งนี้",
  str_homestory_N23dianying_90030601_X7_dialog_content = "คุณเลือกที่จะก้มหน้าก้มตาหรือลุกขึ้นสู้?",
  str_homestory_N23dianying_90030601_X8_dialog_content = "ดำเนินชีวิตตามความคาดหวัง แบกรับความไว้วางใจของประชาชน และตอบคำอธิษฐานของพวกเขา?",
  str_homestory_N23dianying_90030601_X9_dialog_content = "กล้าที่จะกล้าเพื่อคนที่เรารัก",
  str_homestory_N23dianying_90030601_S7_dialog_content = "คุณปล่อยให้ Eclipsites ทำลายบ้านของคุณหรือคุณลุกขึ้นต่อต้านโดยสาบานว่าจะฉีกเนื้อของพวกเขาเป็นชิ้น ๆ แม้กระทั่งฟันของคุณ?",
  str_homestory_N23dianying_90030601_S8_dialog_content = "จำสิ่งที่พวกเขาทำกับคุณและปล่อยให้มันเติมความโกรธของคุณ",
  str_homestory_N23dianying_90030601_S9_dialog_content = "เพื่ออนาคตของ Aurorian และเสรีภาพของลูกหลานของเราทุกคน",
  str_homestory_N23dianying_90030601_8_dialog_content = "คุณจะยอมแพ้และขดตัวในที่ที่คุณอยู่หรือสำรวจโลกที่ไม่รู้จักกับคู่หูของคุณหรือไม่?",
  str_homestory_N23dianying_90030601_9_dialog_content = "สำรวจดินแดนที่สูญหาย เอาชนะอุปสรรคมากมาย รับเทคโนโลยีอันล้ำค่าเพื่อปกป้องอนาคตของ Aurorian",
  str_homestory_N23dianying_90030601_10_dialog_content = "ความมุ่งมั่นอย่างเต็มที่ในการตัดสินใจของคุณจะหมายถึงการประสบกับความอ่อนล้าและความเจ็บปวดไปถึงทุกกระดูกและทุกเส้นประสาทของคุณ",
  str_homestory_N23dianying_90030601_11_dialog_content = "คุณจะกลิ้งไปมาในโคลนขณะที่ถูกผู้สอนตะโกนใส่ จิตใจและร่างกายของคุณจะแตกสลายก่อนที่จะถูกหลอมใหม่",
  str_homestory_N23dianying_90030601_12_dialog_content = "การฝึกฝนอาจดูไร้ความปราณีและโหดร้าย แต่เราทุกคนรู้ดีว่าได้รับความเคารพจากคมดาบ",
  str_homestory_N23dianying_90030601_13_dialog_content = "รอยแผลเป็นที่คุณได้รับจากการฝึกเป็นเครื่องพิสูจน์ความมุ่งมั่นของคุณ",
  str_homestory_N23dianying_90030601_14_dialog_content = "เราเฝ้าระวังในความมืดและขับไล่ศัตรูที่กล้าบุกรุกออกไป",
  str_homestory_N23dianying_90030601_15_dialog_content = "เจตจำนงที่แข็งทื่อของเราจะเผาพวกมันทิ้ง ไม่ว่าพวกมันจะมีกรงเล็บแหลมคมหรือร่างใหญ่โต",
  str_homestory_N23dianying_90030601_16_dialog_content = "เข้าร่วมกับเราและกลายเป็นกระดูกและเนื้อของพยุหเสนาแห่งอิลลูมินา",
  str_homestory_N23dianying_90030601_17_dialog_content = "ต่อสู้เคียงข้างพี่น้องผู้สูงศักดิ์ของคุณในอ้อมแขน และโอบรับตัวตนใหม่ของคุณ",
  str_homestory_N23dianying_90030601_18_dialog_content = "ยืนหยัดกับพวกเขาและปกป้องสิทธิ์ในการเอาชีวิตรอดของชาวออโรเรียนทุกคน",
  str_homestory_N23dianying_90030601_19_dialog_content = "ร่วมกัน คุณคือกำแพงอันยิ่งใหญ่ที่ตั้งอยู่ระหว่างสนามรบที่แห้งแล้งและเตาไฟอันอบอุ่นของคุณ",
  str_homestory_N23dianying_90030601_20_dialog_content = "ฉัน ไรน์ฮาร์ด จอมพลแห่งอิลลูมินา บัญชาการกองทัพอิลลูมินาทั้งหมด...",
  str_homestory_N23dianying_90030601_21_dialog_content = "ปกป้อง Aurorian ทั้งหมดด้วยค่าใช้จ่ายทั้งหมดและจนกว่าจะตาย",
  str_homestory_N23dianying_90030601_22_dialog_content = "ขออิลลูมินาจงเจิดจำรัส!",
  str_homestory_N23dianying_90030601_23_dialog_content = "โอกาสลอตเตอรีฟรีสำหรับทุกคนที่มาเยี่ยมชมศูนย์จัดหางาน Illumina!",
  str_homestory_N23dianying_90030601_24_dialog_content = "รางวัลรวมถึง: กระป๋องปรุงรสของ Gram, ภาพถ่ายพร้อมลายเซ็น Siobhan, เตียง Comfort Expedition ของ Philyshy และอื่นๆ อีกมากมาย!",
  str_homestory_N23dianying_90030601_25_dialog_content = "ผู้โชคดี 100 ท่านแรกจะได้รับบัตรกำนัลประสบการณ์น้ำพุร้อน Cloud Island!",
  str_homestory_N23dianying_90030601_26_dialog_content = "เข้าใจแล้ว. การเสนอรางวัลเพื่อดึงดูดความสนใจเป็นแนวทางที่จำเป็น",
  str_homestory_N23dianying_90030601_27_dialog_content = "เราไปแช่น้ำพุร้อนด้วยกันหลังจากถ่ายทำโฆษณาเสร็จไหม?",
  str_homestory_N23dianying_90030601_X26_dialog_content = "โอกาสลอตเตอรีฟรีสำหรับทุกคนที่มาเยี่ยมชมศูนย์จัดหางาน Illumina!",
  str_homestory_N23dianying_90030601_X27_dialog_content = "รางวัลประกอบด้วย: กระป๋องปรุงรสของ Gram, บัตรกำนัล The Other End Experience, Migard's Succulent Plants และอื่นๆ!",
  str_homestory_N23dianying_90030601_X28_dialog_content = "ผู้โชคดี 100 ท่านแรกจะได้รับ Afternoon Delight Set!",
  str_homestory_N23dianying_90030601_X29_dialog_content = "เรารอเห็นชื่อของคุณอยู่ในรายชื่อรับสมัครงาน!",
  str_homestory_N23dianying_90030601_S26_dialog_content = "โอกาสลอตเตอรีฟรีสำหรับทุกคนที่มาเยี่ยมชมศูนย์จัดหางาน Illumina!",
  str_homestory_N23dianying_90030601_S27_dialog_content = "รางวัลประกอบด้วย: กระป๋องปรุงรสของ Gram, Vida's Mine Detector Lollipop, ไม้เบสบอล Revy's และอื่นๆ!",
  str_homestory_N23dianying_90030601_S28_dialog_content = "ผู้โชคดี 100 ท่านแรกจะได้รับ Voucher Commander Barton Ship Companionship!",
